CREATE OR REPLACE FUNCTION public.register_reception_wrapper(payload jsonb)
    RETURNS jsonb
    LANGUAGE plpgsql
    SECURITY DEFINER
    AS $body$
    DECLARE
      res jsonb;
    BEGIN
      -- Llamar a la función atómica existente. Ajusta el nombre si difiere.
      PERFORM public.register_reception(payload);
      -- Retornar éxito simple. Si la función original retorna datos, es mejor adaptarlo.
      res := jsonb_build_object('status','ok');
      RETURN res;
    END;
    $body$;
    $fn$;
  END IF;
END$$

register_reception.stmt_full:
CREATE OR REPLACE FUNCTION public.register_reception(
      p_store_id uuid,
      p_supplier text,
      p_reception_date date,
      p_invoice_number text,
      p_items jsonb,
      p_user_id uuid
    ) RETURNS jsonb
    LANGUAGE plpgsql
    SECURITY DEFINER
    AS $body$
    DECLARE
      v_receipt_id uuid;
      v_item jsonb;
      v_product_id uuid;
      v_qty integer;
      v_unit_cost numeric;
      v_new_qty integer;
      v_mov jsonb;
      v_res jsonb := jsonb_build_object('status','ok','items',jsonb_build_array());
    BEGIN
      -- Crear receipt
      v_receipt_id := gen_random_uuid();
      INSERT INTO public.receipts(id, created_at, user_id, status, total_cost, reference_doc, notes)
      VALUES (v_receipt_id, now(), p_user_id, 'active', 0, p_invoice_number, p_supplier);

      -- Iterar items: p_items expected as JSON array of objects {product_id, quantity, unit_cost}
      FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
      LOOP
        v_product_id := (v_item->>'product_id')::uuid;
        v_qty := (v_item->>'quantity')::int;
        v_unit_cost := (v_item->>'unit_cost')::numeric;

        -- Insert receipt item
        INSERT INTO public.receipt_items(id, receipt_id, product_id, quantity, unit_cost, created_at)
        VALUES (gen_random_uuid(), v_receipt_id, v_product_id, v_qty, v_unit_cost, now());

        -- Insert movimiento de stock
        INSERT INTO public.stock_movements(id, store_id, product_id, variant_id, quantity_change, movement_type, reference_id, reference_doc, movement_date, created_by, created_at)
        VALUES (gen_random_uuid(), p_store_id, v_product_id, NULL, v_qty, 'purchase'::public.movement_type, v_receipt_id::text, p_invoice_number, now(), p_user_id, now());

        -- Upsert inventory
        INSERT INTO public.inventory (id, store_id, product_id, quantity, updated_at)
        VALUES (gen_random_uuid(), p_store_id, v_product_id, v_qty, now())
        ON CONFLICT (store_id, product_id) DO UPDATE
        SET quantity = public.inventory.quantity + EXCLUDED.quantity,
            updated_at = now();

        -- Obtener nuevo balance
        SELECT quantity INTO v_new_qty FROM public.inventory WHERE store_id = p_store_id AND product_id = v_product_id;

        -- Añadir info al resultado
        v_mov := jsonb_build_object('product_id', v_product_id, 'quantity_added', v_qty, 'new_quantity', v_new_qty);
        v_res := jsonb_set(v_res, '{items}', (v_res->'items') || jsonb_build_array(v_mov));
      END LOOP;

      -- Actualizar total_cost en receipt (opcional)
      UPDATE public.receipts SET total_cost = (
        SELECT COALESCE(SUM(quantity * unit_cost),0) FROM public.receipt_items WHERE receipt_id = v_receipt_id
      ) WHERE id = v_receipt_id;

      v_res := jsonb_set(v_res, '{receipt_id}', to_jsonb(v_receipt_id));
      RETURN v_res;
    END;
    $body$;
    $fn$;
  END IF;
END$$

CREATE OR REPLACE FUNCTION public.register_reception(
    p_store_id UUID,
    p_supplier TEXT,
    p_reception_date DATE,
    p_invoice_number TEXT,
    p_items JSONB
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_reception_id UUID;
    v_item JSONB;
    v_product_id UUID;
    v_quantity INTEGER;
    v_unit_cost NUMERIC;
    v_total_cost NUMERIC := 0;
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid()::UUID;
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

    -- Create receipt record
    INSERT INTO public.receipts (
        user_id,
        total_cost,
        reference_doc,
        created_at,
        status,
        store_id,
        supplier,
        reception_date
    ) VALUES (
        v_user_id,
        0,
        FORMAT('%s | %s', TRIM(p_supplier), TRIM(p_invoice_number)),
        now(),
        'active',
        p_store_id,
        p_supplier,
        p_reception_date
    )
    RETURNING id INTO v_reception_id;

    -- Process items
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_quantity := (v_item->>'quantity')::INTEGER;
        v_unit_cost := (v_item->>'unit_cost')::NUMERIC;

        INSERT INTO public.receipt_items (
            receipt_id,
            product_id,
            quantity,
            unit_cost,
            created_at
        ) VALUES (
            v_reception_id,
            v_product_id,
            v_quantity,
            v_unit_cost,
            now()
        );

        -- Use register_stock_movement
        PERFORM public.register_stock_movement(
            p_store_id,
            v_product_id,
            NULL,
            v_quantity,
            'purchase',
            'Factura: ' || p_invoice_number,
            v_user_id,
            NULL,
            v_reception_id::TEXT
        );

        v_total_cost := v_total_cost + (v_quantity * v_unit_cost);
    END LOOP;

    UPDATE public.receipts SET total_cost = v_total_cost WHERE id = v_reception_id;

    RETURN v_reception_id;
END;
$$

CREATE OR REPLACE FUNCTION register_reception(
    p_store_id UUID,
    p_supplier TEXT,
    p_reception_date DATE,
    p_invoice_number TEXT,
    p_items JSONB
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_reception_id UUID;
    v_item JSONB;
    v_product_id UUID;
    v_quantity NUMERIC;
    v_unit_cost NUMERIC;
    v_total_cost NUMERIC := 0;
    v_items_count INT := 0;
    v_user_id UUID;
    v_user_store_id UUID;
    v_sku TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;
    v_user_id := auth.uid()::UUID;

    -- SECURITY CHECK
    v_user_store_id := public.current_user_store_id();
    IF v_user_store_id IS NULL THEN
        RAISE EXCEPTION 'User has no store assigned';
    END IF;
    IF v_user_store_id != p_store_id THEN
        RAISE EXCEPTION 'Invalid store_id for user';
    END IF;

    -- BASIC VALIDATIONS
    IF p_supplier IS NULL OR TRIM(p_supplier) = '' THEN RAISE EXCEPTION 'Supplier is required'; END IF;
    IF p_reception_date IS NULL THEN RAISE EXCEPTION 'Reception date is required'; END IF;
    IF p_reception_date > CURRENT_DATE THEN RAISE EXCEPTION 'Reception date cannot be in the future'; END IF;
    IF p_invoice_number IS NULL OR TRIM(p_invoice_number) = '' THEN RAISE EXCEPTION 'Invoice number is required'; END IF;

    -- DUPLICATE INVOICE CHECK
    IF EXISTS (
        SELECT 1 FROM receipts r
        JOIN public.profiles p ON p.id = r.user_id
        WHERE p.store_id = p_store_id
          AND r.reference_doc = FORMAT('%s | %s', TRIM(p_supplier), TRIM(p_invoice_number))
          AND r.status = 'active'
    ) THEN
        RAISE EXCEPTION 'Duplicate invoice for this supplier in this store';
    END IF;

    IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Reception must contain at least one item';
    END IF;

    v_items_count := jsonb_array_length(p_items);

    -- CREATE RECEPTION HEADER
    INSERT INTO receipts (
        user_id, total_cost, reference_doc, notes, created_at, status
    ) VALUES (
        v_user_id, 0, FORMAT('%s | %s', TRIM(p_supplier), TRIM(p_invoice_number)), NULL, p_reception_date, 'active'
    )
    RETURNING id INTO v_reception_id;

    -- PROCESS ITEMS
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_sku := v_item->>'sku';
        v_quantity := (v_item->>'quantity')::NUMERIC;
        v_unit_cost := (v_item->>'unit_cost')::NUMERIC;

        -- MATCH BY SKU IF PRODUCT_ID IS MISSING
        IF v_product_id IS NULL AND v_sku IS NOT NULL THEN
            SELECT id INTO v_product_id FROM products
            WHERE store_id = p_store_id AND sku = v_sku;
        END IF;

        IF v_product_id IS NULL THEN
            RAISE EXCEPTION 'Product with SKU % not found in this store', COALESCE(v_sku, 'UNKNOWN');
        END IF;

        IF v_quantity IS NULL OR v_quantity <= 0 THEN RAISE EXCEPTION 'quantity must be greater than 0'; END IF;
        IF v_unit_cost IS NULL OR v_unit_cost < 0 THEN RAISE EXCEPTION 'unit_cost cannot be negative'; END IF;

        -- AUDIT ITEM
        INSERT INTO receipt_items (receipt_id, product_id, quantity, unit_cost, created_at)
        VALUES (v_reception_id, v_product_id, v_quantity, v_unit_cost, NOW());

        -- UPDATE INVENTORY
        INSERT INTO inventory (store_id, product_id, quantity, updated_at, created_at)
        VALUES (p_store_id, v_product_id, v_quantity, NOW(), NOW())
        ON CONFLICT (store_id, product_id) DO UPDATE SET
            quantity = inventory.quantity + v_quantity,
            updated_at = NOW();

        -- STOCK MOVEMENT
        INSERT INTO stock_movements (
            store_id, product_id, quantity_change, movement_type, reference_doc, reference_id, movement_date, created_by, created_at
        ) VALUES (
            p_store_id, v_product_id, v_quantity, 'purchase'::public.movement_type,
            FORMAT('%s | %s', TRIM(p_supplier), TRIM(p_invoice_number)), v_reception_id::TEXT, p_reception_date, v_user_id, NOW()
        );

        v_total_cost := v_total_cost + (v_quantity * v_unit_cost);
    END LOOP;

    -- UPDATE TOTAL COST
    UPDATE receipts SET total_cost = v_total_cost, updated_at = NOW() WHERE id = v_reception_id;

    RETURN v_reception_id;
END;
$$

CREATE OR REPLACE FUNCTION public.register_reception(
