        FORMAT('%s | %s', TRIM(p_supplier), TRIM(p_invoice_number)),
        NULL,
        p_reception_date,
        'active'
    )
    RETURNING id INTO v_reception_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_quantity := (v_item->>'quantity')::NUMERIC;
        v_unit_cost := (v_item->>'unit_cost')::NUMERIC;

        INSERT INTO receipt_items (
            receipt_id,
            product_id,
            quantity,
            unit_cost,
            created_at
        ) VALUES (
            v_reception_id,
            v_product_id,
            v_quantity,
            v_unit_cost,
            NOW()
        );

        INSERT INTO inventory (
            store_id,
            product_id,
            quantity,
            updated_at
        ) VALUES (
            p_store_id,
            v_product_id,
            v_quantity,
            NOW()
        )
        ON CONFLICT (store_id, product_id) DO UPDATE SET
            quantity = inventory.quantity + v_quantity,
            updated_at = NOW();

        INSERT INTO stock_movements (
            store_id,
            product_id,
            quantity_change,
            movement_type,
            reference_doc,
            reference_id,
            movement_date,
            created_by,
            created_at
        ) VALUES (
            p_store_id,
            v_product_id,
            v_quantity,
            'purchase'::public.movement_type,
            FORMAT('%s | %s', TRIM(p_supplier), TRIM(p_invoice_number)),
            v_reception_id::TEXT,
            p_reception_date,
            v_user_id,
            NOW()
        );

        v_total_cost := v_total_cost + (v_quantity * v_unit_cost);
    END LOOP;

    UPDATE receipts SET
        total_cost = v_total_cost,
        updated_at = NOW()
    WHERE id = v_reception_id;

    INSERT INTO audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        store_id,
        created_at
    ) VALUES (
        v_user_id,
        'CREATE',
        'receipts',
        v_reception_id::TEXT,
        NULL,
        jsonb_build_object(
            'supplier', p_supplier,
            'invoice_number', p_invoice_number,
            'items_count', v_items_count,
            'total_cost', v_total_cost
        ),
        p_store_id,
        NOW()
    );

    RETURN v_reception_id;
END;
$$

