CREATE OR REPLACE FUNCTION public.register_stock_movement(
      p_store_id uuid,
      p_product_id uuid,
      p_variant_id uuid,
      p_quantity_change integer,
      p_movement_type text,
      p_reference_doc text,
      p_created_by uuid
    ) RETURNS jsonb
    LANGUAGE plpgsql
    SECURITY DEFINER
    AS $body$
    DECLARE
      v_inventory_id uuid;
      v_new_qty integer;
      v_res jsonb;
    BEGIN
      -- Insertar movimiento
      INSERT INTO public.stock_movements(
        store_id, product_id, variant_id, quantity_change, movement_type, reference_doc, movement_date, created_by, created_at
      ) VALUES (
        p_store_id, p_product_id, p_variant_id, p_quantity_change, p_movement_type::public.movement_type, p_reference_doc, now(), p_created_by, now()
      );

      -- Upsert inventario: si existe fila, sumar quantity_change; si no, crear nueva
      INSERT INTO public.inventory (id, store_id, product_id, quantity, updated_at)
      VALUES (gen_random_uuid(), p_store_id, p_product_id, GREATEST(p_quantity_change,0), now())
      ON CONFLICT (store_id, product_id) DO UPDATE
      SET quantity = public.inventory.quantity + EXCLUDED.quantity,
          updated_at = now();

      -- Obtener nuevo balance
      SELECT quantity INTO v_new_qty FROM public.inventory WHERE store_id = p_store_id AND product_id = p_product_id;

      v_res := jsonb_build_object('status','ok','new_quantity',v_new_qty);
      RETURN v_res;
    END;
    $body$;
    $fn$;
  END IF;
END$$

CREATE OR REPLACE FUNCTION public.register_stock_movement(
  p_store_id uuid,
  p_product_id uuid,
  p_variant_id uuid,
  p_quantity_change integer,
  p_movement_type text,
  p_reference_doc text,
  p_created_by uuid,
  p_inventory_version integer DEFAULT NULL  
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $body$
DECLARE
  v_new_qty integer;
  v_new_version integer;
  v_res jsonb;
BEGIN
  -- Insert movement
  INSERT INTO public.stock_movements(
    store_id, product_id, variant_id, quantity_change, movement_type, reference_doc, movement_date, created_by, created_at
  ) VALUES (
    p_store_id, p_product_id, p_variant_id, p_quantity_change, p_movement_type::public.movement_type, p_reference_doc, now(), p_created_by, now()
  );

  -- Upsert inventario with optimistic locking
  INSERT INTO public.inventory (id, store_id, product_id, quantity, version, updated_at)
  VALUES (gen_random_uuid(), p_store_id, p_product_id, p_quantity_change, 1, now()) -- Corrected logic
  ON CONFLICT (store_id, product_id) DO UPDATE
  SET quantity = public.inventory.quantity + p_quantity_change,
      version = public.inventory.version + 1,
      updated_at = now()
  WHERE (p_inventory_version IS NULL OR public.inventory.version = p_inventory_version) -- Handle null version
  RETURNING quantity, version INTO v_new_qty, v_new_version;

  -- Verify that a row was updated (if a version was provided)
  IF p_inventory_version IS NOT NULL AND NOT FOUND THEN
    RAISE EXCEPTION 'Concurrency error: Inventory version mismatch';
  END IF;

  v_res := jsonb_build_object('status', 'ok', 'new_quantity', v_new_qty, 'new_version', v_new_version);
  RETURN v_res;
END;
$body$

CREATE OR REPLACE FUNCTION public.register_stock_movement(
  p_store_id uuid,
  p_product_id uuid,
  p_variant_id uuid,
  p_quantity_change integer,
  p_movement_type text,
  p_reference_doc text,
  p_created_by uuid,
  p_inventory_version integer DEFAULT NULL,
  p_reference_id text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $body$
DECLARE
  v_new_qty integer;
  v_new_version integer;
  v_res jsonb;
BEGIN
  -- Optimistic locking check
  IF p_inventory_version IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.inventory
      WHERE store_id = p_store_id
        AND product_id = p_product_id
        AND version = p_inventory_version
    ) THEN
      RAISE EXCEPTION 'Concurrency error: Inventory version mismatch';
    END IF;
  END IF;

  -- Insert movement. This will fire tr_sync_inventory_after_movement
  -- which in turn updates the inventory table.
  INSERT INTO public.stock_movements(
    store_id, product_id, variant_id, quantity_change, movement_type, reference_id, reference_doc, movement_date, created_by, created_at
  ) VALUES (
    p_store_id, p_product_id, p_variant_id, p_quantity_change, p_movement_type::public.movement_type, p_reference_id, p_reference_doc, now(), p_created_by, now()
  );

  -- Retrieve the updated quantity and version from inventory
  -- These were updated by the trigger during the INSERT above
  SELECT quantity, version INTO v_new_qty, v_new_version
  FROM public.inventory
  WHERE store_id = p_store_id AND product_id = p_product_id;

  v_res := jsonb_build_object('status', 'ok', 'new_quantity', v_new_qty, 'new_version', v_new_version);
  RETURN v_res;
END;
$body$

CREATE OR REPLACE FUNCTION public.register_stock_movement(
  p_product_id uuid,
  p_store_id uuid,
  p_user_id uuid,
  p_quantity integer,
  p_movement_type text,
  p_reason text,
  p_sale_id uuid DEFAULT NULL,
  p_unit_cost numeric DEFAULT 0,
  p_notes text DEFAULT NULL,
  p_variant_id uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_new_qty integer;
  v_new_version integer;
BEGIN
  IF NOT public.has_store_access(p_store_id) THEN
    RAISE EXCEPTION 'Unauthorized store access' USING ERRCODE = '42501';
  END IF;

  IF p_quantity = 0 THEN RETURN jsonb_build_object('status', 'skipped', 'message', 'Zero quantity'); END IF;

  INSERT INTO public.stock_movements (
    product_id, store_id, created_by, variant_id, quantity_change,
    movement_type, reference_id, reference_doc, unit_cost, notes, movement_date, created_at, tenant_id
  ) VALUES (
    p_product_id, p_store_id, p_user_id, p_variant_id, p_quantity,
    LOWER(p_movement_type)::public.movement_type, p_sale_id::text, p_reason,
    COALESCE(p_unit_cost, 0), p_notes, now(), now(), (SELECT tenant_id FROM public.stores WHERE id = p_store_id)
  );

  SELECT quantity, version INTO v_new_qty, v_new_version
  FROM public.inventory
  WHERE store_id = p_store_id AND product_id = p_product_id;

  RETURN jsonb_build_object(
    'status', 'ok',
    'new_quantity', COALESCE(v_new_qty, 0),
    'new_version', COALESCE(v_new_version, 0)
  );
END;
$$

CREATE OR REPLACE FUNCTION public.register_stock_movement(
  p_product_id uuid, p_store_id uuid, p_quantity numeric,
  p_movement_type text DEFAULT NULL, p_reason text DEFAULT NULL,
  p_user_id uuid DEFAULT NULL, p_variant_id uuid DEFAULT NULL,
  p_sale_id uuid DEFAULT NULL, p_unit_cost numeric DEFAULT NULL,
  p_notes text DEFAULT NULL, p_operation_date timestamp with time zone DEFAULT NULL,
  p_skip_access_check boolean DEFAULT FALSE
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $func$
DECLARE
  v_new_qty NUMERIC; v_new_version BIGINT;
  v_eff TIMESTAMP WITH TIME ZONE := COALESCE(p_operation_date, NOW());
  v_dist_costs NUMERIC := 0;
BEGIN
  IF NOT p_skip_access_check AND NOT public.has_store_access(p_store_id) THEN
    RAISE EXCEPTION 'Unauthorized store access';
  END IF;
  IF p_quantity = 0 THEN RETURN jsonb_build_object('status','skipped'); END IF;

  INSERT INTO public.stock_movements (
    product_id, store_id, created_by, variant_id, quantity_change,
    movement_type, reference_id, reference_doc, unit_cost, notes, movement_date, created_at
  ) VALUES (
    p_product_id, p_store_id, p_user_id, p_variant_id, p_quantity,
    LOWER(p_movement_type)::public.movement_type, p_sale_id::text, p_reason,
    COALESCE(p_unit_cost,0), p_notes, v_eff, v_eff
  ) RETURNING balance_after INTO v_new_qty;

  SELECT version INTO v_new_version FROM public.inventory
  WHERE product_id = p_product_id AND store_id = p_store_id;

  UPDATE public.products SET stock_current = v_new_qty, updated_at = v_eff
  WHERE id = p_product_id AND store_id = p_store_id;

  -- FIX F4-01: PMP incluye costos asociados distribuidos
  IF COALESCE(p_unit_cost,0) > 0 AND p_quantity > 0 THEN
    SELECT COALESCE(SUM(scd.distribution_amount),0) INTO v_dist_costs
    FROM public.service_cost_distributions scd
    JOIN public.receipts r ON r.id = scd.receipt_id
    WHERE scd.product_id = p_product_id AND r.store_id = p_store_id AND r.status != 'voided';

    UPDATE public.products SET cost_average = (
      SELECT CASE WHEN SUM(sm.quantity_change) = 0 THEN 0
        ELSE ROUND((SUM(sm.unit_cost * sm.quantity_change) + v_dist_costs) / SUM(sm.quantity_change), 4)
      END
      FROM public.stock_movements sm
      WHERE sm.product_id = p_product_id AND sm.store_id = p_store_id AND sm.quantity_change > 0
    ), updated_at = v_eff WHERE id = p_product_id AND store_id = p_store_id;
  END IF;

  INSERT INTO public.business_events (event_type, entity_id, payload, created_at) VALUES (
    'stock_movement', p_product_id,
    jsonb_build_object('store_id',p_store_id,'qty',p_quantity,'type',LOWER(p_movement_type),'new_qty',v_new_qty),
    v_eff
  );
  RETURN jsonb_build_object('status','ok','new_quantity',v_new_qty,'new_version',v_new_version);
END;
$func$

