CREATE OR REPLACE FUNCTION public.create_sale(
  p_store_id uuid,
  p_seller_id uuid,
  p_payment_method text,
  p_total_amount numeric,
  p_subtotal numeric,
  p_discount_type text,
  p_discount_value numeric,
  p_items jsonb,
  p_applied_taxes jsonb DEFAULT '[]'::jsonb,
  p_tax_amount numeric DEFAULT 0
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_transaction_id uuid;
  v_item jsonb;
  v_units_to_deduct integer;
  v_conversion_factor integer;
  v_current_stock integer;
  v_product_name text;
  v_product_id uuid;
  v_variant_id uuid;
BEGIN
  -- Security
  IF NOT (public.is_admin() OR public.has_store_access(p_store_id)) THEN
    RAISE EXCEPTION 'Access Denied to Store';
  END IF;

  -- 1. PRE-VALIDATE STOCK
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_variant_id := (v_item->>'variant_id')::uuid;
    v_units_to_deduct := (v_item->>'quantity')::integer;

    IF v_variant_id IS NOT NULL THEN
      SELECT conversion_factor INTO v_conversion_factor FROM public.product_variants WHERE id = v_variant_id;
      v_units_to_deduct := v_units_to_deduct * COALESCE(v_conversion_factor, 1);
    END IF;

    SELECT quantity INTO v_current_stock FROM public.inventory WHERE store_id = p_store_id AND product_id = v_product_id;

    IF COALESCE(v_current_stock, 0) < v_units_to_deduct THEN
      SELECT name INTO v_product_name FROM public.products WHERE id = v_product_id;
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: % (Disponible: %, Requerido: %)',
        COALESCE(v_product_name, 'Producto desconocido'), COALESCE(v_current_stock, 0), v_units_to_deduct;
    END IF;
  END LOOP;

  -- 2. CREATE TRANSACTION
  INSERT INTO public.transactions (
    store_id, seller_id, total_amount, subtotal, discount_type, discount_value,
    payment_method, status, tax_amount, applied_taxes
  ) VALUES (
    p_store_id, p_seller_id, p_total_amount, p_subtotal,
    p_discount_type::public.discount_type_enum, p_discount_value,
    p_payment_method::public.payment_method_enum, 'completed'::public.transaction_status,
    p_tax_amount, p_applied_taxes
  ) RETURNING id INTO v_transaction_id;

  -- 3. PROCESS ITEMS
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_variant_id := (v_item->>'variant_id')::uuid;
    v_units_to_deduct := (v_item->>'quantity')::integer;

    IF v_variant_id IS NOT NULL THEN
      SELECT conversion_factor INTO v_conversion_factor FROM public.product_variants WHERE id = v_variant_id;
      v_units_to_deduct := v_units_to_deduct * COALESCE(v_conversion_factor, 1);
    END IF;

    INSERT INTO public.transaction_items (
      transaction_id, product_id, variant_id, quantity, price_at_sale, cost_at_sale
    ) VALUES (
      v_transaction_id, v_product_id, v_variant_id,
      (v_item->>'quantity')::integer, (v_item->>'price')::numeric, (v_item->>'cost')::numeric
    );

    PERFORM public.register_stock_movement(
      p_product_id := v_product_id,
      p_store_id := p_store_id,
      p_user_id := p_seller_id,
      p_quantity := -v_units_to_deduct,
      p_movement_type := 'sale',
      p_reason := 'Venta #' || substring(v_transaction_id::text from 1 for 8),
      p_sale_id := v_transaction_id,
      p_unit_cost := COALESCE((v_item->>'cost')::numeric, 0),
      p_variant_id := v_variant_id
    );
  END LOOP;

  RETURN v_transaction_id;
END;
$$

CREATE OR REPLACE FUNCTION public.create_sale(
  p_store_id uuid,
  p_seller_id uuid,
  p_payment_method text,
  p_total_amount numeric,
  p_subtotal numeric,
  p_discount_type text,
  p_discount_value numeric,
  p_items jsonb,
  p_applied_taxes jsonb DEFAULT '[]'::jsonb,
  p_tax_amount numeric DEFAULT 0
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_transaction_id uuid;
  v_item jsonb;
  v_product_id uuid;
  v_variant_id uuid;
  v_quantity_requested integer;
  v_units_to_deduct integer;
  v_current_stock integer;
  v_product_name text;
  v_conversion_factor integer;
BEGIN
  -- Security
  IF NOT (public.is_admin() OR public.has_store_access(p_store_id)) THEN
    RAISE EXCEPTION 'Access Denied to Store';
  END IF;

  -- 1. PRE-VALIDATE STOCK WITH AGGREGATION AND LOCKING
  -- We aggregate all required units per product first and LOCK the rows.
  FOR v_product_id, v_units_to_deduct IN
    WITH item_list AS (
      SELECT
        (elem->>'product_id')::uuid as prod_id,
        (elem->>'variant_id')::uuid as var_id,
        (elem->>'quantity')::numeric::integer as qty
      FROM jsonb_array_elements(p_items) as elem
    ),
    item_conversions AS (
      SELECT
        il.prod_id,
        il.qty * COALESCE(pv.conversion_factor, 1) as base_qty
      FROM item_list il
      LEFT JOIN public.product_variants pv ON pv.id = il.var_id
    )
    SELECT prod_id, SUM(base_qty)::integer
    FROM item_conversions
    GROUP BY prod_id
    ORDER BY prod_id -- Deadlock prevention
  LOOP
    -- Lock row for update
    SELECT quantity INTO v_current_stock
    FROM public.inventory
    WHERE store_id = p_store_id AND product_id = v_product_id
    FOR UPDATE;

    IF COALESCE(v_current_stock, 0) < v_units_to_deduct THEN
      SELECT name INTO v_product_name FROM public.products WHERE id = v_product_id;
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: % (Disponible: %, Requerido: %)',
        COALESCE(v_product_name, 'Producto desconocido'), COALESCE(v_current_stock, 0), v_units_to_deduct;
    END IF;
  END LOOP;

  -- 2. CREATE TRANSACTION
  INSERT INTO public.transactions (
    store_id, seller_id, total_amount, subtotal, discount_type, discount_value,
    payment_method, status, tax_amount, applied_taxes
  ) VALUES (
    p_store_id, p_seller_id, p_total_amount, p_subtotal,
    p_discount_type::public.discount_type_enum, p_discount_value,
    p_payment_method::public.payment_method_enum, 'completed'::public.transaction_status,
    p_tax_amount, p_applied_taxes
  ) RETURNING id INTO v_transaction_id;

  -- 3. PROCESS ITEMS
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_variant_id := (v_item->>'variant_id')::uuid;
    v_quantity_requested := (v_item->>'quantity')::numeric::integer;

    v_units_to_deduct := v_quantity_requested;
    IF v_variant_id IS NOT NULL THEN
      SELECT conversion_factor INTO v_conversion_factor FROM public.product_variants WHERE id = v_variant_id;
      v_units_to_deduct := v_quantity_requested * COALESCE(v_conversion_factor, 1);
    END IF;

    INSERT INTO public.transaction_items (
      transaction_id, product_id, variant_id, quantity, price_at_sale, cost_at_sale
    ) VALUES (
      v_transaction_id, v_product_id, v_variant_id,
      v_quantity_requested, (v_item->>'price')::numeric, (v_item->>'cost')::numeric
    );

    PERFORM public.register_stock_movement(
      p_product_id := v_product_id,
      p_store_id := p_store_id,
      p_user_id := p_seller_id,
      p_quantity := -v_units_to_deduct,
      p_movement_type := 'sale',
      p_reason := 'Venta #' || substring(v_transaction_id::text from 1 for 8),
      p_sale_id := v_transaction_id,
      p_unit_cost := COALESCE((v_item->>'cost')::numeric, 0),
      p_variant_id := v_variant_id
    );
  END LOOP;

  RETURN v_transaction_id;
END;
$$

CREATE OR REPLACE FUNCTION public.create_sale(
  p_store_id uuid,
  p_seller_id uuid,
  p_payment_method text,
  p_total_amount numeric,
  p_subtotal numeric,
  p_discount_type text,
  p_discount_value numeric,
  p_items jsonb,
  p_applied_taxes jsonb DEFAULT '[]'::jsonb,
  p_tax_amount numeric DEFAULT 0,
  p_transaction_id uuid DEFAULT NULL  
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_transaction_id uuid;
  v_item jsonb;
  v_product_id uuid;
  v_units_to_deduct integer;
  v_current_stock integer;
  v_product_name text;
BEGIN
  -- 🛡️ RBAC Enforcement
  IF NOT (public.is_admin() OR public.has_role('clerk')) THEN
    RAISE EXCEPTION 'Access Denied: Required role Clerk or Admin';
  END IF;

  -- 🛡️ Store Isolation
  IF NOT public.has_store_access(p_store_id) THEN
    RAISE EXCEPTION 'Access Denied to Store';
  END IF;

  -- 🛡️ Idempotency Check
  IF p_transaction_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.transactions WHERE id = p_transaction_id) THEN
      RETURN p_transaction_id; -- Already processed
    END IF;
    v_transaction_id := p_transaction_id;
  ELSE
    v_transaction_id := gen_random_uuid();
  END IF;

  -- 🔄 PHASE 1: PRE-VALIDATE & LOCK (Ordered to prevent deadlocks)
  -- 1a. Lock PRODUCTS first (Master)
  FOR v_product_id IN
    SELECT DISTINCT (elem->>'product_id')::uuid FROM jsonb_array_elements(p_items) as elem ORDER BY 1
  LOOP
    PERFORM 1 FROM public.products WHERE id = v_product_id FOR UPDATE;
  END LOOP;

  -- 1b. Lock INVENTORY second
  FOR v_product_id, v_units_to_deduct IN
    WITH item_list AS (
      SELECT
        (elem->>'product_id')::uuid as prod_id,
        (elem->>'variant_id')::uuid as var_id,
        (elem->>'quantity')::numeric::integer as qty
      FROM jsonb_array_elements(p_items) as elem
    ),
    item_conversions AS (
      SELECT
        il.prod_id,
        il.qty * COALESCE(pv.conversion_factor, 1) as base_qty
      FROM item_list il
      LEFT JOIN public.product_variants pv ON pv.id = il.var_id
    )
    SELECT prod_id, SUM(base_qty)::integer
    FROM item_conversions
    GROUP BY prod_id
    ORDER BY prod_id
  LOOP
    SELECT quantity INTO v_current_stock FROM public.inventory
    WHERE store_id = p_store_id AND product_id = v_product_id FOR UPDATE;

    IF COALESCE(v_current_stock, 0) < v_units_to_deduct THEN
      SELECT name INTO v_product_name FROM public.products WHERE id = v_product_id;
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: % (Disponible: %, Requerido: %)',
        COALESCE(v_product_name, 'Producto desconocido'), COALESCE(v_current_stock, 0), v_units_to_deduct;
    END IF;
  END LOOP;

  -- 🔄 PHASE 2: PERSISTENCE
  INSERT INTO public.transactions (
    id, store_id, seller_id, total_amount, subtotal, discount_type, discount_value,
    payment_method, status, tax_amount, applied_taxes
  ) VALUES (
    v_transaction_id, p_store_id, p_seller_id, p_total_amount, p_subtotal,
    p_discount_type::public.discount_type_enum, p_discount_value,
    p_payment_method::public.payment_method_enum, 'completed'::public.transaction_status,
    p_tax_amount, p_applied_taxes
  );

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO public.transaction_items (
      transaction_id, product_id, variant_id, quantity, price_at_sale, cost_at_sale
    ) VALUES (
      v_transaction_id,
      (v_item->>'product_id')::uuid,
      (v_item->>'variant_id')::uuid,
      (v_item->>'quantity')::numeric::integer,
      (v_item->>'price')::numeric,
      (v_item->>'cost')::numeric
    );

    PERFORM public.register_stock_movement(
      p_product_id := (v_item->>'product_id')::uuid,
      p_store_id := p_store_id,
      p_user_id := p_seller_id,
      p_quantity := -((v_item->>'quantity')::numeric::integer),
      p_movement_type := 'sale',
      p_reason := 'Venta #' || substring(v_transaction_id::text from 1 for 8),
      p_sale_id := v_transaction_id,
      p_unit_cost := COALESCE((v_item->>'cost')::numeric, 0),
      p_variant_id := (v_item->>'variant_id')::uuid
    );
  END LOOP;

  RETURN v_transaction_id;
END;
$$

CREATE OR REPLACE FUNCTION public.create_sale(
  p_store_id uuid,
  p_seller_id uuid,
  p_payment_method text,
  p_total_amount numeric,
  p_subtotal numeric,
  p_discount_type text,
  p_discount_value numeric,
  p_items jsonb,
  p_applied_taxes jsonb DEFAULT '[]'::jsonb,
  p_tax_amount numeric DEFAULT 0,
  p_transaction_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_transaction_id uuid;
  v_item jsonb;
  v_product_id uuid;
  v_units_to_deduct integer;
  v_current_stock integer;
  v_product_name text;
  v_idempotent_res JSONB;
BEGIN
  IF p_transaction_id IS NOT NULL THEN
      SELECT response_data->>'id' INTO v_idempotent_res FROM public.idempotency_keys WHERE id = p_transaction_id;
      IF FOUND THEN RETURN v_idempotent_res::UUID; END IF;
  END IF;

  IF NOT (public.is_admin() OR public.has_role('clerk')) THEN
    RAISE EXCEPTION 'Access Denied: Required role Clerk or Admin';
  END IF;

  IF NOT public.has_store_access(p_store_id) THEN
    RAISE EXCEPTION 'Access Denied to Store';
  END IF;

  v_transaction_id := COALESCE(p_transaction_id, gen_random_uuid());

  FOR v_product_id IN
    SELECT DISTINCT (elem->>'product_id')::uuid FROM jsonb_array_elements(p_items) as elem ORDER BY 1
  LOOP
    PERFORM 1 FROM public.products WHERE id = v_product_id FOR UPDATE;

    SELECT quantity INTO v_current_stock FROM public.inventory
    WHERE store_id = p_store_id AND product_id = v_product_id FOR UPDATE;

    SELECT SUM((elem->>'quantity')::integer) INTO v_units_to_deduct
    FROM jsonb_array_elements(p_items) as elem
    WHERE (elem->>'product_id')::uuid = v_product_id;

    IF COALESCE(v_current_stock, 0) < v_units_to_deduct THEN
      SELECT name INTO v_product_name FROM public.products WHERE id = v_product_id;
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: % (Disponible: %, Requerido: %)',
        COALESCE(v_product_name, 'Producto desconocido'), COALESCE(v_current_stock, 0), v_units_to_deduct;
    END IF;
  END LOOP;

  INSERT INTO public.transactions (
    id, store_id, seller_id, total_amount, subtotal, discount_type, discount_value,
    payment_method, status, tax_amount, applied_taxes, tenant_id
  ) VALUES (
    v_transaction_id, p_store_id, p_seller_id, p_total_amount, p_subtotal,
    p_discount_type::public.discount_type_enum, p_discount_value,
    p_payment_method::public.payment_method_enum, 'completed'::public.transaction_status,
    p_tax_amount, p_applied_taxes, (SELECT tenant_id FROM public.stores WHERE id = p_store_id)
  );

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_units_to_deduct := (v_item->>'quantity')::integer;

    INSERT INTO public.transaction_items (
      transaction_id, product_id, quantity, price_at_sale, cost_at_sale
    ) VALUES (
      v_transaction_id, v_product_id, v_units_to_deduct,
      (v_item->>'price')::numeric, (v_item->>'cost')::numeric
    );

    PERFORM public.register_stock_movement(
      p_product_id := v_product_id,
      p_store_id := p_store_id,
      p_user_id := p_seller_id,
      p_quantity := -v_units_to_deduct,
      p_movement_type := 'sale',
      p_reason := 'Venta #' || substring(v_transaction_id::text from 1 for 8),
      p_sale_id := v_transaction_id,
      p_unit_cost := COALESCE((v_item->>'cost')::numeric, 0)
    );
  END LOOP;

  IF p_transaction_id IS NOT NULL THEN
      INSERT INTO public.idempotency_keys (id, user_id, request_path, payload_hash, response_data, status)
      VALUES (p_transaction_id, auth.uid(), 'create_sale', '', jsonb_build_object('id', v_transaction_id), 'completed');
  END IF;

  PERFORM public.log_audit_event('CREATE_SALE', jsonb_build_object('sale_id', v_transaction_id), p_store_id);

  RETURN v_transaction_id;
END;
$$

CREATE OR REPLACE FUNCTION public.create_sale(
  p_store_id UUID,
  p_seller_id UUID,
  p_total_amount NUMERIC,
  p_items JSONB,
  p_subtotal NUMERIC DEFAULT 0,
  p_discount_type TEXT DEFAULT 'fixed',
  p_discount_value NUMERIC DEFAULT 0,
  p_payment_method TEXT DEFAULT 'cash',
  p_tax_amount NUMERIC DEFAULT 0,
  p_applied_taxes JSONB DEFAULT '[]'::jsonb,
  p_transaction_id UUID DEFAULT NULL,


  p_operation_date TIMESTAMP WITH TIME ZONE DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_transaction_id UUID;
  v_item JSONB;
  v_product_id UUID;
  v_units_to_deduct NUMERIC;
  v_current_stock NUMERIC;
  v_tenant_id UUID;
  v_effective_date TIMESTAMP WITH TIME ZONE;
BEGIN
  -- 0) Validación de política forward-only
  -- Si p_operation_date es NULL, no validamos (usa NOW() implícito).
  -- Si viene una fecha, validamos que no sea anterior al MAX global.
  PERFORM public.validate_operation_date(p_operation_date);
  v_effective_date := COALESCE(p_operation_date, NOW());

  -- 1) Internal security check
  IF NOT public.has_store_access(p_store_id) THEN
    RAISE EXCEPTION 'Unauthorized store access';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.stores WHERE id = p_store_id;
  v_transaction_id := COALESCE(p_transaction_id, gen_random_uuid());

  -- 2) Insert transaction header con la fecha efectiva
  INSERT INTO public.transactions (
    id, store_id, seller_id, total_amount, subtotal, tenant_id, status,
    payment_method, discount_type, discount_value, tax_amount, applied_taxes,
    created_at  -- NUEVO: usar la fecha de operación efectiva
  )
  VALUES (
    v_transaction_id, p_store_id, p_seller_id, p_total_amount, p_subtotal, v_tenant_id,
    'completed'::transaction_status,
    p_payment_method::payment_method_enum,
    p_discount_type::discount_type_enum,
    p_discount_value, p_tax_amount, p_applied_taxes,
    v_effective_date
  );

  -- 3) Process items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_units_to_deduct := (v_item->>'quantity')::NUMERIC;

    -- Lock product record
    PERFORM 1 FROM public.products WHERE id = v_product_id FOR UPDATE;

    -- Check inventory stock
    SELECT quantity INTO v_current_stock FROM public.inventory
      WHERE store_id = p_store_id AND product_id = v_product_id FOR UPDATE;

    IF COALESCE(v_current_stock, 0) < v_units_to_deduct THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: Producto % tiene % unidades, se requieren %', v_product_id, COALESCE(v_current_stock, 0), v_units_to_deduct;
    END IF;

    -- Insert item (con fecha efectiva)
