    v_item_currency := COALESCE(v_item->>'currency', 'CUP');
    v_item_rate := COALESCE((v_item->>'exchange_rate')::numeric, 1.0);
    v_price_cup := v_price * v_item_rate;
    v_cost_cup := v_cost * v_item_rate;

