CREATE OR REPLACE FUNCTION public.fn_sync_inventory_on_movement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $function$
DECLARE
    v_new_qty integer;
    v_exists boolean;
BEGIN
    -- Check if record exists
    SELECT EXISTS (
        SELECT 1 FROM public.inventory
        WHERE store_id = NEW.store_id AND product_id = NEW.product_id
    ) INTO v_exists;

    IF NOT v_exists THEN
        -- If it doesn't exist and we are subtracting, it's an error
        IF NEW.quantity_change < 0 THEN
            RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: No hay registro de inventario para el producto %', NEW.product_id;
        END IF;

        INSERT INTO public.inventory (store_id, product_id, quantity, version, updated_at)
        VALUES (NEW.store_id, NEW.product_id, NEW.quantity_change, 1, now())
        RETURNING quantity INTO v_new_qty;
    ELSE
        -- If it exists, update it. This handles the negative change safely.
        UPDATE public.inventory
        SET quantity = public.inventory.quantity + NEW.quantity_change,
            version = public.inventory.version + 1,
            updated_at = now()
        WHERE store_id = NEW.store_id AND product_id = NEW.product_id
        RETURNING quantity INTO v_new_qty;

        -- Final check after update
        IF v_new_qty < 0 THEN
            RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: El stock no puede ser negativo para el producto % (Resultado: %)', NEW.product_id, v_new_qty;
        END IF;
    END IF;

    NEW.balance_after := v_new_qty;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_inventory_on_movement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $function$
DECLARE
    v_current_qty integer;
    v_new_qty integer;
BEGIN
    -- Get current quantity if exists
    SELECT quantity INTO v_current_qty
    FROM public.inventory
    WHERE store_id = NEW.store_id AND product_id = NEW.product_id;

    -- Calculate new quantity
    v_new_qty := COALESCE(v_current_qty, 0) + NEW.quantity_change;

    -- Explicit validation before update/insert
    IF v_new_qty < 0 THEN
        RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: Product % (Store: %) cannot go below 0. Current: %, Change: %, Result: %',
            NEW.product_id, NEW.store_id, COALESCE(v_current_qty, 0), NEW.quantity_change, v_new_qty;
    END IF;

    -- Perform atomic upsert
    INSERT INTO public.inventory (store_id, product_id, quantity, version, updated_at)
    VALUES (NEW.store_id, NEW.product_id, NEW.quantity_change, 1, now())
    ON CONFLICT (store_id, product_id)
    DO UPDATE SET
        quantity = public.inventory.quantity + EXCLUDED.quantity,
        version = public.inventory.version + 1,
        updated_at = now()
    RETURNING quantity INTO v_new_qty;

    NEW.balance_after := v_new_qty;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_inventory_on_movement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_new_qty numeric;
  v_exists boolean;
  v_product_stock numeric;
BEGIN
  -- Bypass durante restauración
  IF current_setting('app.restore_mode', true) = 'true' THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS(SELECT 1 FROM public.inventory WHERE store_id = NEW.store_id AND product_id = NEW.product_id) INTO v_exists;
  IF NOT v_exists THEN
    SELECT stock_current INTO v_product_stock FROM public.products WHERE id = NEW.product_id;
    v_new_qty := COALESCE(v_product_stock, 0) + NEW.quantity_change;
    IF v_new_qty < 0 THEN
      v_new_qty := 0;
    END IF;
    INSERT INTO public.inventory (store_id, product_id, quantity, version, updated_at)
    VALUES (NEW.store_id, NEW.product_id, v_new_qty, 1, now())
    ON CONFLICT DO NOTHING;
  ELSE
    UPDATE public.inventory
    SET quantity = public.inventory.quantity + NEW.quantity_change,
        version = public.inventory.version + 1,
        updated_at = now()
    WHERE store_id = NEW.store_id AND product_id = NEW.product_id
    RETURNING quantity INTO v_new_qty;
    IF v_new_qty < 0 THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: El stock no puede ser negativo para el producto % (Resultado: %)', NEW.product_id, v_new_qty;
    END IF;
  END IF;
  NEW.balance_after := v_new_qty;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.fn_sync_inventory_on_movement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public, pg_temp
AS $function$
DECLARE
  v_new_qty numeric;
  v_exists boolean;
BEGIN
  -- Bypass durante restauración
  IF current_setting('app.restore_mode', true) = 'true' THEN
    RETURN NEW;
  END IF;

  -- Check if inventory record exists for this product+store
  SELECT EXISTS(
    SELECT 1 FROM public.inventory
    WHERE store_id = NEW.store_id AND product_id = NEW.product_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    -- FIX: inventory no existe → base = 0 (NO leer products.stock_current)
    -- products.stock_current es un cache derivado y puede estar desincronizado.
    v_new_qty := NEW.quantity_change;

    IF v_new_qty < 0 THEN
      -- FIX: rechazar ventas/ajustes negativos cuando no hay inventory
      -- Antes: GREATEST(v_new_qty, 0) silenciaba el error → balance_after=0
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: No hay inventario para el producto % en tienda %. No se puede registrar una salida.', NEW.product_id, NEW.store_id;
    END IF;

    -- quantity_change > 0: crear inventory con esa cantidad
    INSERT INTO public.inventory (store_id, product_id, quantity, version, updated_at)
    VALUES (NEW.store_id, NEW.product_id, v_new_qty, 1, now())
    ON CONFLICT DO NOTHING;
  ELSE
    -- inventory existe: usar inventory.quantity como fuente (CORRECTO)
    -- SELECT FOR UPDATE ya está implícito en el UPDATE ... RETURNING
    UPDATE public.inventory
    SET quantity = public.inventory.quantity + NEW.quantity_change,
        version = public.inventory.version + 1,
        updated_at = now()
    WHERE store_id = NEW.store_id AND product_id = NEW.product_id
    RETURNING quantity INTO v_new_qty;

    IF v_new_qty < 0 THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: El stock no puede ser negativo para el producto % (Resultado: %)', NEW.product_id, v_new_qty;
    END IF;
  END IF;

  NEW.balance_after := v_new_qty;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_inventory_on_movement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public, pg_temp
AS $function$
DECLARE
  v_new_qty numeric;
  v_exists boolean;
  v_product_store_id uuid;
BEGIN
  -- Bypass durante restauración
  IF current_setting('app.restore_mode', true) = 'true' THEN
    RETURN NEW;
  END IF;

  -- FIX H-01: Validar que el producto existe y su store_id coincide
  SELECT store_id INTO v_product_store_id FROM public.products WHERE id = NEW.product_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ERR_PRODUCT_NOT_FOUND: Producto % no existe', NEW.product_id;
  END IF;
  IF NEW.store_id IS NULL THEN
    RAISE EXCEPTION 'ERR_STORE_MISMATCH: store_id es NULL para el producto %', NEW.product_id;
  END IF;
  IF v_product_store_id IS NULL THEN
    RAISE EXCEPTION 'ERR_STORE_MISMATCH: products.store_id es NULL para el producto %', NEW.product_id;
  END IF;
  IF NEW.store_id IS DISTINCT FROM v_product_store_id THEN
    RAISE EXCEPTION 'ERR_STORE_MISMATCH: movement store_id % no coincide con product store_id % para el producto %',
      NEW.store_id, v_product_store_id, NEW.product_id;
  END IF;

  -- Check if inventory record exists for this product+store
  SELECT EXISTS(
    SELECT 1 FROM public.inventory
    WHERE store_id = NEW.store_id AND product_id = NEW.product_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    -- inventory no existe → base = 0
    v_new_qty := NEW.quantity_change;

    IF v_new_qty < 0 THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: No hay inventario para el producto % en tienda %. No se puede registrar una salida.', NEW.product_id, NEW.store_id;
    END IF;

    INSERT INTO public.inventory (store_id, product_id, quantity, version, updated_at)
    VALUES (NEW.store_id, NEW.product_id, v_new_qty, 1, now())
    ON CONFLICT DO NOTHING;
  ELSE
    UPDATE public.inventory
    SET quantity = public.inventory.quantity + NEW.quantity_change,
        version = public.inventory.version + 1,
        updated_at = now()
    WHERE store_id = NEW.store_id AND product_id = NEW.product_id
    RETURNING quantity INTO v_new_qty;

    IF v_new_qty < 0 THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: El stock no puede ser negativo para el producto % (Resultado: %)', NEW.product_id, v_new_qty;
    END IF;
  END IF;

  NEW.balance_after := v_new_qty;
  RETURN NEW;
END;
$function$

