CREATE OR REPLACE FUNCTION public.validate_active_store()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.active_store_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.user_store_access
            WHERE user_id = NEW.id AND store_id = NEW.active_store_id
        ) THEN
            RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: The user does not have access to the selected store.';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.validate_active_store()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.active_store_id IS NOT NULL THEN
        -- Check in user_store_memberships (the new source of truth)
        IF NOT EXISTS (
            SELECT 1 FROM public.user_store_memberships
            WHERE user_id = NEW.id
              AND store_id = NEW.active_store_id
              AND status = 'active'
        ) THEN
            RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: The user does not have active membership in the selected store.';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.validate_active_store()
RETURNS TRIGGER AS $$
DECLARE
    v_role user_role;
BEGIN
    -- Get user role
    v_role := NEW.role;

    -- If role is 'costo', active_store_id is optional
    IF v_role = 'costo'::user_role THEN
        IF NEW.active_store_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.user_store_memberships
                WHERE user_id = NEW.id
                  AND store_id = NEW.active_store_id
                  AND status = 'active'
            ) THEN
                RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: The user does not have active membership in the selected store.';
            END IF;
        END IF;
    ELSE
        -- For operational roles, ensure active_store_id is NOT NULL and valid
        IF NEW.active_store_id IS NULL THEN
             IF v_role IN ('encargado'::user_role, 'clerk'::user_role, 'warehouse'::user_role) THEN
                RAISE EXCEPTION 'ERR_STORE_REQUIRED: El rol % requiere una tienda activa asignada.', v_role;
             END IF;
        ELSE
            IF NOT EXISTS (
                SELECT 1 FROM public.user_store_memberships
                WHERE user_id = NEW.id
                  AND store_id = NEW.active_store_id
                  AND status = 'active'
            ) THEN
                RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: The user does not have active membership in the selected store.';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.validate_active_store()
RETURNS TRIGGER AS $$
DECLARE
    v_role user_role;
BEGIN
    v_role := NEW.role;

    -- Si role es 'costo' o 'admin' o 'superadmin', active_store_id es opcional
    IF v_role = 'costo'::user_role
       OR v_role = 'admin'::user_role
       OR v_role = 'superadmin'::user_role THEN
        IF NEW.active_store_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.user_store_memberships
                WHERE user_id = NEW.id
                  AND store_id = NEW.active_store_id
                  AND status = 'active'
            ) THEN
                -- En INSERT, permitir (la membership se creará después)
                -- En UPDATE, sí exigir consistencia
                IF TG_OP = 'UPDATE' THEN
                    RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: El usuario no tiene membership activa en la tienda seleccionada.';
                END IF;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    -- Para roles operativos (encargado, clerk, warehouse, manager, usuario)
    IF TG_OP = 'INSERT' THEN
        -- En INSERT: ser permisivo. La función managed_create_user inserta
        -- memberships justo después. Solo validar si active_store_id NO es NULL
        -- Y la membership ya existe (caso admin directo).
        IF NEW.active_store_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.user_store_memberships
                WHERE user_id = NEW.id
                  AND store_id = NEW.active_store_id
                  AND status = 'active'
            ) THEN
                -- No fallar — la membership se creará en la misma transacción
                -- gestionada por managed_create_user (SECURITY DEFINER).
                -- Solo marcar para revisión posterior vía UPDATE.
                RETURN NEW;
            END IF;
        END IF;
        RETURN NEW;
    ELSE
        -- UPDATE: validación estricta
        IF NEW.active_store_id IS NULL THEN
            IF v_role IN ('encargado'::user_role, 'clerk'::user_role, 'warehouse'::user_role) THEN
                RAISE EXCEPTION 'ERR_STORE_REQUIRED: El rol % requiere una tienda activa asignada.', v_role;
            END IF;
        ELSE
            IF NOT EXISTS (
                SELECT 1 FROM public.user_store_memberships
                WHERE user_id = NEW.id
                  AND store_id = NEW.active_store_id
                  AND status = 'active'
            ) THEN
                RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: El usuario no tiene membership activa en la tienda seleccionada.';
            END IF;
        END IF;
        RETURN NEW;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.validate_active_store()
RETURNS TRIGGER AS $$
DECLARE
    v_role user_role;
BEGIN
    v_role := NEW.role;

    -- Si role es 'costo' o 'admin' o 'superadmin', active_store_id es opcional
    IF v_role = 'costo'::user_role
       OR v_role = 'admin'::user_role
       OR v_role = 'superadmin'::user_role THEN
        -- Solo validar si active_store_id cambió o es INSERT
        IF TG_OP = 'INSERT' OR (OLD.active_store_id IS DISTINCT FROM NEW.active_store_id) THEN
            IF NEW.active_store_id IS NOT NULL THEN
                IF NOT EXISTS (
                    SELECT 1 FROM public.user_store_memberships
                    WHERE user_id = NEW.id
                      AND store_id = NEW.active_store_id
                      AND status = 'active'
                ) THEN
                    IF TG_OP = 'UPDATE' THEN
                        RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: El usuario no tiene membership activa en la tienda seleccionada.';
                    END IF;
                END IF;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    -- Para roles operativos (encargado, clerk, warehouse, manager, usuario)
    IF TG_OP = 'INSERT' THEN
        -- En INSERT: ser permisivo. La función managed_create_user inserta
        -- memberships justo después. No validar nada aquí.
        RETURN NEW;
    ELSE
        -- UPDATE: solo validar si active_store_id cambió realmente
        -- (evita bloquear updates de otros campos en perfiles intermedios)
        IF OLD.active_store_id IS NOT DISTINCT FROM NEW.active_store_id THEN
            -- active_store_id no cambió → permitir el UPDATE sin validar
            RETURN NEW;
        END IF;

        -- active_store_id cambió → validar consistencia
        IF NEW.active_store_id IS NULL THEN
            IF v_role IN ('encargado'::user_role, 'clerk'::user_role, 'warehouse'::user_role) THEN
                RAISE EXCEPTION 'ERR_STORE_REQUIRED: El rol % requiere una tienda activa asignada.', v_role;
            END IF;
        ELSE
            IF NOT EXISTS (
                SELECT 1 FROM public.user_store_memberships
                WHERE user_id = NEW.id
                  AND store_id = NEW.active_store_id
                  AND status = 'active'
            ) THEN
                RAISE EXCEPTION 'ERR_INVALID_ACTIVE_STORE: El usuario no tiene membership activa en la tienda seleccionada.';
            END IF;
        END IF;
        RETURN NEW;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

enforce_encargado_store_limit.stmt_full:
CREATE OR REPLACE FUNCTION public.enforce_encargado_store_limit()
RETURNS TRIGGER AS $$
DECLARE
    v_creator_role user_role;
    v_limit integer;
    v_current_count integer;
BEGIN
    IF NEW.created_by IS NULL THEN RETURN NEW; END IF;

    SELECT role, max_stores_limit INTO v_creator_role, v_limit
    FROM public.profiles WHERE id = NEW.created_by;

    IF v_creator_role = 'encargado' THEN
        SELECT COUNT(*) INTO v_current_count FROM public.stores WHERE created_by = NEW.created_by;
        IF v_current_count >= v_limit THEN
            RAISE EXCEPTION 'ERR_STORE_LIMIT_EXCEEDED: Maximum number of stores reached for this manager (%/%)', v_current_count, v_limit;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

enforce_encargado_user_limit.stmt_full:
CREATE OR REPLACE FUNCTION public.enforce_encargado_user_limit()
RETURNS TRIGGER AS $$
DECLARE
    v_creator_role user_role;
    v_limit integer;
    v_current_count integer;
BEGIN
    IF NEW.created_by IS NULL THEN RETURN NEW; END IF;

    SELECT role, max_users_limit INTO v_creator_role, v_limit
    FROM public.profiles WHERE id = NEW.created_by;

    IF v_creator_role = 'encargado' THEN
        SELECT COUNT(*) INTO v_current_count FROM public.profiles WHERE created_by = NEW.created_by;
        IF v_current_count >= v_limit THEN
            RAISE EXCEPTION 'ERR_USER_LIMIT_EXCEEDED: Maximum number of users reached for this manager (%/%)', v_current_count, v_limit;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

auto_assign_store_to_creator.stmt_full:
CREATE OR REPLACE FUNCTION public.auto_assign_store_to_creator()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.created_by IS NOT NULL THEN
        INSERT INTO public.user_store_access (user_id, store_id, assigned_by)
        VALUES (NEW.created_by, NEW.id, NEW.created_by)
        ON CONFLICT DO NOTHING;

        -- If the creator has no active store, set this as active
        UPDATE public.profiles
        SET active_store_id = NEW.id
        WHERE id = NEW.created_by AND active_store_id IS NULL;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.auto_assign_store_to_creator()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.created_by IS NOT NULL THEN
        -- Insert into memberships
        INSERT INTO public.user_store_memberships (user_id, store_id, role, status)
        VALUES (NEW.created_by, NEW.id, 'admin', 'active')
        ON CONFLICT (user_id, store_id) DO NOTHING;

        -- Also keep user_store_access updated for legacy compatibility if it exists
        IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'user_store_access') THEN
            INSERT INTO public.user_store_access (user_id, store_id, assigned_by)
            VALUES (NEW.created_by, NEW.id, NEW.created_by)
            ON CONFLICT (user_id, store_id) DO NOTHING;
        END IF;

        -- If the creator has no active store, set this as active
        UPDATE public.profiles
        SET active_store_id = NEW.id
        WHERE id = NEW.created_by AND active_store_id IS NULL;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

managed_create_user.stmt_full:
CREATE OR REPLACE FUNCTION public.managed_create_user(
    p_email text,
    p_full_name text,
    p_role user_role,
    p_store_id uuid,  
    p_max_stores integer DEFAULT 0,
    p_max_users integer DEFAULT 0
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $$
DECLARE
    v_user_id uuid;
    v_creator_role user_role;
BEGIN
    SELECT role INTO v_creator_role FROM public.profiles WHERE id = auth.uid();

    IF v_creator_role NOT IN ('admin', 'encargado') THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Only admins and managers can create users.';
    END IF;

    -- Note: trigger_enforce_encargado_user_limit handles the limit check on INSERT.

    -- We use a random UUID here as per the existing pattern,
    -- though in a real Supabase setup this would usually be linked to an auth.user.
    INSERT INTO public.profiles (
        id, email, full_name, role, active_store_id, is_active,
        created_by, max_stores_limit, max_users_limit, created_at, updated_at
    )
    VALUES (
        gen_random_uuid(), p_email, p_full_name, p_role, p_store_id, true,
        auth.uid(), p_max_stores, p_max_users, now(), now()
    )
    RETURNING id INTO v_user_id;

    -- Also assign the store access
    IF p_store_id IS NOT NULL THEN
        INSERT INTO public.user_store_access (user_id, store_id, assigned_by)
        VALUES (v_user_id, p_store_id, auth.uid());
    END IF;

    INSERT INTO public.business_events (event_type, entity_id, payload, created_at)
    VALUES ('user_account_created', v_user_id, jsonb_build_object('email', p_email, 'created_by', auth.uid()::text), now());

    RETURN jsonb_build_object('success', true, 'user_id', v_user_id, 'email', p_email, 'message', 'User created');
END;
$$

CREATE OR REPLACE FUNCTION public.managed_create_user(
    p_email text,
    p_full_name text,
    p_role user_role,  
    p_store_id uuid,  
    p_memberships JSONB DEFAULT NULL,  
    p_max_stores integer DEFAULT 0,
    p_max_users integer DEFAULT 0
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $$
DECLARE
    v_user_id uuid;
    v_creator_role user_role;
    v_active_store_id uuid;
    m JSONB;
BEGIN
    SELECT role INTO v_creator_role FROM public.profiles WHERE id = auth.uid();

    IF v_creator_role NOT IN ('admin', 'encargado') THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Only admins and managers can create users.';
    END IF;

    -- Determine initial active_store_id
    IF p_memberships IS NOT NULL AND jsonb_array_length(p_memberships) > 0 THEN
        v_active_store_id := (p_memberships->0->>'store_id')::UUID;
    ELSE
        v_active_store_id := p_store_id;
    END IF;

    INSERT INTO public.profiles (
        id, email, full_name, role, active_store_id, is_active,
        created_by, max_stores_limit, max_users_limit, created_at, updated_at
    )
    VALUES (
        gen_random_uuid(), p_email, p_full_name, p_role, v_active_store_id, true,
        auth.uid(), p_max_stores, p_max_users, now(), now()
    )
    RETURNING id INTO v_user_id;

    -- Handle memberships
    IF p_memberships IS NOT NULL THEN
        FOR m IN SELECT * FROM jsonb_array_elements(p_memberships)
        LOOP
            INSERT INTO public.user_store_memberships (user_id, store_id, role)
            VALUES (v_user_id, (m->>'store_id')::UUID, (m->>'role')::user_role);
        END LOOP;
    ELSIF p_store_id IS NOT NULL THEN
        -- Fallback to legacy single store assignment
        INSERT INTO public.user_store_memberships (user_id, store_id, role)
        VALUES (v_user_id, p_store_id, p_role);
    END IF;

    INSERT INTO public.business_events (event_type, entity_id, payload, created_at)
    VALUES ('user_account_created', v_user_id, jsonb_build_object('email', p_email, 'created_by', auth.uid()::text), now());

    RETURN jsonb_build_object('success', true, 'user_id', v_user_id, 'email', p_email, 'message', 'User created');
END;
$$

CREATE OR REPLACE FUNCTION public.managed_create_user(
    p_email text,
    p_full_name text,
    p_role user_role,
    p_store_id uuid,
    p_memberships JSONB DEFAULT NULL,
    p_max_stores integer DEFAULT 0,
    p_max_users integer DEFAULT 0
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $$
DECLARE
    v_user_id uuid := gen_random_uuid();
    v_creator_role user_role;
    v_active_store_id uuid;
    m JSONB;
BEGIN
    SELECT role INTO v_creator_role FROM public.profiles WHERE id = auth.uid();

    IF v_creator_role NOT IN ('admin', 'encargado') THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Only admins and managers can create users.';
    END IF;

    -- 1. Create entry in auth.users
    -- We use a default password 'demo123' hashed with blowfish (standard for this project)
    INSERT INTO auth.users (
        id, instance_id, aud, role, email, encrypted_password,
        email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
        created_at, updated_at, confirmation_token, email_change,
        email_change_token_new, recovery_token
    )
    VALUES (
        v_user_id,
        '00000000-0000-0000-0000-000000000000',
        'authenticated',
        'authenticated',
        p_email,
        extensions.crypt('demo123', extensions.gen_salt('bf')),
        now(),
        '{"provider": "email", "providers": ["email"]}',
        jsonb_build_object('full_name', p_full_name),
        now(),
        now(),
        '', '', '', ''
    );

    -- 2. Determine initial active_store_id
    IF p_memberships IS NOT NULL AND jsonb_array_length(p_memberships) > 0 THEN
        v_active_store_id := (p_memberships->0->>'store_id')::UUID;
    ELSE
        v_active_store_id := p_store_id;
    END IF;

    -- 3. Create entry in public.profiles
    INSERT INTO public.profiles (
        id, email, full_name, role, active_store_id, is_active,
        created_by, max_stores_limit, max_users_limit, created_at, updated_at
    )
    VALUES (
        v_user_id, p_email, p_full_name, p_role, v_active_store_id, true,
        auth.uid(), p_max_stores, p_max_users, now(), now()
    );

    -- 4. Handle memberships
    IF p_memberships IS NOT NULL THEN
        FOR m IN SELECT * FROM jsonb_array_elements(p_memberships)
        LOOP
            INSERT INTO public.user_store_memberships (user_id, store_id, role)
            VALUES (v_user_id, (m->>'store_id')::UUID, (m->>'role')::user_role);
        END LOOP;
    ELSIF p_store_id IS NOT NULL THEN
        INSERT INTO public.user_store_memberships (user_id, store_id, role)
        VALUES (v_user_id, p_store_id, p_role);
    END IF;

    INSERT INTO public.business_events (event_type, entity_id, payload, created_at)
    VALUES ('user_account_created', v_user_id, jsonb_build_object('email', p_email, 'created_by', auth.uid()::text), now());

    RETURN jsonb_build_object('success', true, 'user_id', v_user_id, 'email', p_email, 'message', 'User created with auth account');
END;
$$

CREATE OR REPLACE FUNCTION public.managed_create_user(
    p_email text,
    p_full_name text,
    p_role user_role,
    p_store_id uuid,
    p_memberships JSONB DEFAULT NULL,
    p_max_stores integer DEFAULT 0,
    p_max_users integer DEFAULT 0,
    p_target_user_id uuid DEFAULT NULL  
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $$
DECLARE
    v_user_id uuid;
    v_role_id uuid;
    v_active_store_id uuid;
    m JSONB;
BEGIN
    -- Hierarchy check (only if not called by service role)
    -- Note: In a real environment, we'd check if the caller is an admin or service role
    IF NOT public.can_create_user_with_role(p_role::text) THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: You do not have permission to create a user with role %', p_role;
    END IF;

    -- Determine initial active_store_id
    IF p_memberships IS NOT NULL AND jsonb_array_length(p_memberships) > 0 THEN
        v_active_store_id := (p_memberships->0->>'store_id')::UUID;
    ELSE
        v_active_store_id := p_store_id;
    END IF;

    -- Get the matching role_id from roles table
    SELECT id INTO v_role_id FROM public.roles
    WHERE lower(name) = lower(p_role::text)
       OR (name = 'Cajero' AND p_role = 'clerk')
       OR (name = 'Almacenero' AND p_role = 'warehouse')
    LIMIT 1;

    v_user_id := COALESCE(p_target_user_id, gen_random_uuid());

    INSERT INTO public.profiles (
        id, email, full_name, role, role_id, active_store_id, is_active,
        created_by, max_stores_limit, max_users_limit, created_at, updated_at
    )
    VALUES (
        v_user_id, p_email, p_full_name, p_role, v_role_id, v_active_store_id, true,
        auth.uid(), p_max_stores, p_max_users, now(), now()
    )
    ON CONFLICT (id) DO UPDATE SET
        email = EXCLUDED.email,
        full_name = EXCLUDED.full_name,
        role = EXCLUDED.role,
        role_id = EXCLUDED.role_id,
        active_store_id = EXCLUDED.active_store_id,
        max_stores_limit = EXCLUDED.max_stores_limit,
        max_users_limit = EXCLUDED.max_users_limit,
        updated_at = now()
    RETURNING id INTO v_user_id;

    -- Handle memberships
    IF p_memberships IS NOT NULL THEN
        -- Delete existing if we are updating (conflict case)
        DELETE FROM public.user_store_memberships WHERE user_id = v_user_id;

        FOR m IN SELECT * FROM jsonb_array_elements(p_memberships)
        LOOP
            INSERT INTO public.user_store_memberships (user_id, store_id, role)
            VALUES (v_user_id, (m->>'store_id')::UUID, (m->>'role')::user_role);
        END LOOP;
    ELSIF p_store_id IS NOT NULL THEN
        INSERT INTO public.user_store_memberships (user_id, store_id, role)
        VALUES (v_user_id, p_store_id, p_role)
        ON CONFLICT (user_id, store_id) DO UPDATE SET role = EXCLUDED.role;
    END IF;

    INSERT INTO public.business_events (event_type, entity_id, payload, created_at)
    VALUES ('user_account_managed_created', v_user_id, jsonb_build_object('email', p_email, 'created_by', auth.uid()::text), now());

    RETURN jsonb_build_object('success', true, 'user_id', v_user_id, 'email', p_email, 'message', 'User profile created/synced');
END;
$$

CREATE OR REPLACE FUNCTION public.managed_create_user(p_email text, p_full_name text, p_role user_role, p_store_id uuid DEFAULT NULL::uuid, p_memberships jsonb DEFAULT NULL::jsonb, p_max_stores integer DEFAULT 0, p_max_users integer DEFAULT 0, p_target_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_user_id uuid;
    v_role_id uuid;
    v_active_store_id uuid;
    m JSONB;
    v_creator_role user_role;
BEGIN
    SELECT role INTO v_creator_role FROM public.profiles WHERE id = auth.uid();
    IF v_creator_role IS NULL OR v_creator_role NOT IN ('admin', 'encargado') THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Only admins and managers can create users.';
    END IF;

    v_active_store_id := COALESCE((p_memberships->0->>'store_id')::UUID, p_store_id);

    IF v_creator_role = 'encargado' AND v_active_store_id IS NOT NULL THEN
        IF NOT public.has_store_access(v_active_store_id) THEN
            RAISE EXCEPTION 'ERR_UNAUTHORIZED: No access to store %', v_active_store_id;
        END IF;
    END IF;

    SELECT id INTO v_role_id FROM public.roles WHERE lower(name) = lower(p_role::text) OR (name = 'Cajero' AND p_role = 'clerk') OR (name = 'Almacenero' AND p_role = 'warehouse') LIMIT 1;
    v_user_id := COALESCE(p_target_user_id, gen_random_uuid());

    INSERT INTO public.profiles (id, email, full_name, role, role_id, active_store_id, is_active, created_by, max_stores_limit, max_users_limit, created_at, updated_at)
    VALUES (v_user_id, p_email, p_full_name, p_role, v_role_id, v_active_store_id, true, auth.uid(), p_max_stores, p_max_users, now(), now())
    ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email, full_name = EXCLUDED.full_name, role = EXCLUDED.role, role_id = EXCLUDED.role_id, active_store_id = EXCLUDED.active_store_id, updated_at = now()
    RETURNING id INTO v_user_id;

    IF p_memberships IS NOT NULL THEN
        IF v_creator_role != 'admin' THEN
            DELETE FROM public.user_store_memberships WHERE user_id = v_user_id AND store_id IN (SELECT store_id FROM public.user_store_memberships WHERE user_id = auth.uid() AND role IN ('encargado', 'manager'));
        ELSE
            DELETE FROM public.user_store_memberships WHERE user_id = v_user_id;
        END IF;
        FOR m IN SELECT * FROM jsonb_array_elements(p_memberships) LOOP
            IF (m->>'store_id') IS NOT NULL AND (m->>'store_id') <> '' THEN
                IF v_creator_role = 'admin' OR public.has_store_access((m->>'store_id')::UUID) THEN
                    INSERT INTO public.user_store_memberships (user_id, store_id, role) VALUES (v_user_id, (m->>'store_id')::UUID, (m->>'role')::user_role) ON CONFLICT (user_id, store_id) DO UPDATE SET role = EXCLUDED.role;
                END IF;
            END IF;
        END LOOP;
    ELSIF p_store_id IS NOT NULL THEN
        INSERT INTO public.user_store_memberships (user_id, store_id, role) VALUES (v_user_id, p_store_id, p_role) ON CONFLICT (user_id, store_id) DO UPDATE SET role = EXCLUDED.role;
    END IF;
    RETURN jsonb_build_object('success', true, 'user_id', v_user_id);
END;
$function$

has_store_access.stmt_full:
CREATE OR REPLACE FUNCTION public.has_store_access(p_store_id uuid)
RETURNS boolean AS $$
BEGIN
    RETURN (
        public.is_admin()
        OR
        EXISTS (
            SELECT 1 FROM public.user_store_access
            WHERE user_id = auth.uid() AND store_id = p_store_id
        )
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.has_store_access(p_store_id uuid)
RETURNS boolean AS $$
DECLARE
    v_user_tenant_id UUID;
    v_store_tenant_id UUID;
BEGIN
    SELECT tenant_id INTO v_user_tenant_id FROM public.profiles WHERE id = auth.uid();
    SELECT tenant_id INTO v_store_tenant_id FROM public.stores WHERE id = p_store_id;

    IF v_user_tenant_id IS NOT NULL AND v_store_tenant_id IS NOT NULL AND v_user_tenant_id != v_store_tenant_id THEN
        RETURN FALSE;
    END IF;

    RETURN (
        public.is_admin()
        OR
        EXISTS (
            SELECT 1 FROM public.user_store_memberships
            WHERE user_id = auth.uid()
              AND store_id = p_store_id
              AND status = 'active'
        )
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public

has_role.stmt_full:
CREATE OR REPLACE FUNCTION public.has_role(required_role user_role)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $$
DECLARE
    v_actual_role user_role;
BEGIN
    SELECT role INTO v_actual_role FROM public.profiles WHERE id = auth.uid();

    -- Compatibility mapping
    IF v_actual_role = 'encargado' AND required_role = 'manager' THEN RETURN true; END IF;
    IF v_actual_role = 'usuario' AND (required_role = 'clerk' OR required_role = 'warehouse') THEN RETURN true; END IF;

    RETURN v_actual_role = required_role;
END;
$$

CREATE OR REPLACE FUNCTION public.has_role(p_user_id UUID, p_required_role public.user_role)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $$
DECLARE
    v_actual_role public.user_role;
BEGIN
    SELECT role INTO v_actual_role FROM public.profiles WHERE id = p_user_id;

    IF v_actual_role IS NULL THEN
        RETURN false;
    END IF;

    -- Compatibility mapping (mirroring the 1-arg version)
    IF v_actual_role = 'encargado' AND p_required_role = 'manager' THEN RETURN true; END IF;
    IF v_actual_role = 'usuario' AND (p_required_role = 'clerk' OR p_required_role = 'warehouse') THEN RETURN true; END IF;

    RETURN v_actual_role = p_required_role;
END;
$$

has_any_role.stmt_full:
CREATE OR REPLACE FUNCTION public.has_any_role(required_roles user_role[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $$
DECLARE
    v_actual_role user_role;
    r user_role;
BEGIN
    SELECT role INTO v_actual_role FROM public.profiles WHERE id = auth.uid();

    FOREACH r IN ARRAY required_roles
    LOOP
        IF v_actual_role = r THEN RETURN true; END IF;
        IF v_actual_role = 'encargado' AND r = 'manager' THEN RETURN true; END IF;
        IF v_actual_role = 'usuario' AND (r = 'clerk' OR r = 'warehouse') THEN RETURN true; END IF;
    END LOOP;

    RETURN false;
END;
$$

manage_user_memberships.stmt_full:
CREATE OR REPLACE FUNCTION public.manage_user_memberships(
    p_user_id UUID,
    p_memberships JSONB  
)
RETURNS VOID AS $$
DECLARE
    m JSONB;
    v_creator_role user_role;
BEGIN
    -- SECURITY CHECK: Only admin or authorized encargado can manage memberships
    SELECT role INTO v_creator_role FROM public.profiles WHERE id = auth.uid();
    IF v_creator_role NOT IN ('admin', 'encargado') THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Only admins and managers can manage user memberships.';
    END IF;

    -- Delete existing memberships for this user to replace with new state
    DELETE FROM public.user_store_memberships WHERE user_id = p_user_id;

    FOR m IN SELECT * FROM jsonb_array_elements(p_memberships)
    LOOP
        INSERT INTO public.user_store_memberships (user_id, store_id, role)
        VALUES (
            p_user_id,
            (m->>'store_id')::UUID,
            (m->>'role')::user_role
        );
    END LOOP;

    -- Ensure active_store_id is still valid for the user
    UPDATE public.profiles
    SET active_store_id = (
        SELECT store_id FROM public.user_store_memberships
        WHERE user_id = p_user_id LIMIT 1
    )
    WHERE id = p_user_id
    AND (
        active_store_id NOT IN (SELECT store_id FROM public.user_store_memberships WHERE user_id = p_user_id)
        OR active_store_id IS NULL
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.manage_user_memberships(
    p_user_id UUID,
    p_memberships JSONB  
)
RETURNS VOID AS $$
DECLARE
    m JSONB;
    v_caller_role text;
BEGIN
    -- SECURITY CHECK: Use helper to get role safely
    v_caller_role := public.get_my_role();

    IF v_caller_role NOT IN ('admin', 'encargado') THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Only admins and managers can manage user memberships.';
    END IF;

    -- Replacement logic
    IF v_caller_role = 'admin' THEN
        -- Admins can replace all memberships
        DELETE FROM public.user_store_memberships WHERE user_id = p_user_id;
    ELSE
        -- Encargados can only replace memberships for stores they manage
        -- This prevents accidental deletion of memberships in stores they don't see
        DELETE FROM public.user_store_memberships
        WHERE user_id = p_user_id
        AND store_id IN (
            SELECT store_id FROM public.user_store_memberships
            WHERE user_id = auth.uid()
              AND role IN ('encargado', 'manager')
              AND status = 'active'
        );
    END IF;

    -- Insert new/updated memberships
    IF p_memberships IS NOT NULL AND jsonb_array_length(p_memberships) > 0 THEN
        FOR m IN SELECT * FROM jsonb_array_elements(p_memberships)
        LOOP
            -- Basic validation: Ensure store_id is not null/empty
            IF (m->>'store_id') IS NOT NULL AND (m->>'store_id') <> '' THEN
                -- If not admin, check if they are manager of this store
                IF v_caller_role = 'admin' OR public.is_store_manager((m->>'store_id')::UUID) THEN
                    INSERT INTO public.user_store_memberships (user_id, store_id, role)
                    VALUES (
                        p_user_id,
                        (m->>'store_id')::UUID,
                        (m->>'role')::user_role
                    )
                    ON CONFLICT (user_id, store_id) DO UPDATE SET role = EXCLUDED.role;
                END IF;
            END IF;
        END LOOP;
    END IF;

    -- Ensure active_store_id is still valid for the user
    UPDATE public.profiles
    SET active_store_id = (
        SELECT store_id FROM public.user_store_memberships
        WHERE user_id = p_user_id AND status = 'active' LIMIT 1
    )
    WHERE id = p_user_id
    AND (
        active_store_id NOT IN (SELECT store_id FROM public.user_store_memberships WHERE user_id = p_user_id AND status = 'active')
        OR active_store_id IS NULL
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

