CREATE OR REPLACE FUNCTION public.create_transfer(
    p_origin_store_id UUID,
    p_destination_store_id UUID,
    p_items JSONB,
    p_notes TEXT DEFAULT NULL,
    p_operation_date TIMESTAMPTZ DEFAULT NOW()
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_transfer_id UUID;
    v_item RECORD;
    v_product RECORD;
    v_stock NUMERIC;
BEGIN
    -- Validar que origin != destination
    IF p_origin_store_id = p_destination_store_id THEN
        RAISE EXCEPTION 'ERR_SAME_STORE: La tienda origen y destino deben ser diferentes';
    END IF;

    -- Validar acceso del usuario a la tienda origen
    IF NOT public.has_store_access(p_origin_store_id) THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: No tienes acceso a la tienda origen';
    END IF;

    -- 1. Insertar cabecera
    INSERT INTO public.transfers (origin_store_id, destination_store_id, created_by, notes)
    VALUES (p_origin_store_id, p_destination_store_id, auth.uid(), p_notes)
    RETURNING id INTO v_transfer_id;

    -- 2. Insertar items + VALIDAR STOCK en tienda origen
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(product_id UUID, quantity INTEGER, unit_cost NUMERIC)
    LOOP
        -- Validar que el quantity sea positivo
        IF v_item.quantity <= 0 THEN
            RAISE EXCEPTION 'ERR_INVALID_QUANTITY: La cantidad debe ser mayor a 0 para el producto %', v_item.product_id;
        END IF;

        -- Validar stock suficiente en tienda origen (con FOR UPDATE para concurrencia)
        SELECT stock_current INTO v_stock
        FROM public.products
        WHERE id = v_item.product_id AND store_id = p_origin_store_id
        FOR UPDATE;

        IF v_stock IS NULL THEN
            RAISE EXCEPTION 'ERR_PRODUCT_NOT_FOUND: Producto % no encontrado en tienda origen', v_item.product_id;
        END IF;

        IF v_stock < v_item.quantity THEN
            RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK: Stock insuficiente para producto % (disponible: %, solicitado: %)',
                v_item.product_id, v_stock, v_item.quantity;
        END IF;

        -- Insertar item
        INSERT INTO public.transfer_items (transfer_id, product_id, quantity, unit_cost)
        VALUES (v_transfer_id, v_item.product_id, v_item.quantity, v_item.unit_cost);
    END LOOP;

    RETURN v_transfer_id;
END;
$$

CREATE OR REPLACE FUNCTION public.create_transfer(
  p_origin_store_id uuid,
  p_destination_store_id uuid,
  p_items jsonb,
  p_notes text DEFAULT NULL,
  p_transaction_id uuid DEFAULT NULL,
  p_operation_date timestamp with time zone DEFAULT NULL
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_transfer_id UUID := COALESCE(p_transaction_id, gen_random_uuid());
    v_item RECORD;
    v_server_unit_cost NUMERIC;  -- V2.5: server-side, no cliente
    v_effective_date TIMESTAMP WITH TIME ZONE := COALESCE(p_operation_date, NOW());
    v_caller_uid UUID := auth.uid();
BEGIN
    -- V2.5 H1a: autorización BOLA — el caller debe tener acceso a AMBAS tiendas
    -- Si v_caller_uid IS NULL → service_role (desde API route que ya validó), bypass
    IF v_caller_uid IS NOT NULL THEN
      IF NOT public.has_store_access(p_origin_store_id) THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED_ORIGIN';
      END IF;
      IF NOT public.has_store_access(p_destination_store_id) THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED_DESTINATION';
      END IF;
    END IF;

    PERFORM public.validate_transfer_operation_date(p_operation_date, p_origin_store_id, p_destination_store_id);

    INSERT INTO public.transfers (
      id, origin_store_id, destination_store_id, created_by, notes, tenant_id, created_at
    )
    VALUES (
      v_transfer_id, p_origin_store_id, p_destination_store_id, v_caller_uid, p_notes,
      (SELECT tenant_id FROM public.stores WHERE id = p_origin_store_id),
      v_effective_date
    );

    -- V2.5 (Costo server-side): ignorar unit_cost del cliente y usar products.cost_average
    -- del store origen. Esto previene manipulación del WAC por parte del cliente.
    FOR v_item IN
      SELECT * FROM jsonb_to_recordset(p_items) AS x(
        product_id UUID,
        quantity NUMERIC,
        unit_cost NUMERIC,         -- ignorado, recalculado server-side
        tasa_cambio NUMERIC        -- ignorado, no se necesita (cost_average ya está en CUP)
      )
    LOOP
        SELECT cost_average INTO v_server_unit_cost
        FROM public.products
        WHERE id = v_item.product_id AND store_id = p_origin_store_id;
        IF v_server_unit_cost IS NULL THEN
          -- producto no existe en origen o no tiene cost_average: usar 0 y log
          v_server_unit_cost := 0;
        END IF;

        INSERT INTO public.transfer_items (transfer_id, product_id, quantity, unit_cost, created_at)
        VALUES (v_transfer_id, v_item.product_id, v_item.quantity, v_server_unit_cost, v_effective_date);
    END LOOP;
    RETURN v_transfer_id;
END;
$function$

