CREATE OR REPLACE FUNCTION public.confirm_transfer(
  p_transfer_id UUID,
  p_user_id UUID,
  p_operation_date TIMESTAMPTZ DEFAULT NOW()
) RETURNS JSONB AS $$
DECLARE
  v_transfer RECORD;
  v_item RECORD;
  v_dest_product RECORD;
  v_result JSONB;
  v_movement JSONB;
  v_movements JSONB[] := ARRAY[]::JSONB[];
BEGIN
  -- FIX T5-01: SELECT FOR UPDATE + validar status
  SELECT * INTO v_transfer FROM public.transfers WHERE id = p_transfer_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transferencia no encontrada';
  END IF;

  -- FIX T5-01: solo se puede confirmar si está PENDIENTE
  IF v_transfer.status <> 'PENDIENTE' THEN
    RAISE EXCEPTION 'ERR_TRANSFER_NOT_PENDING: La transferencia ya fue confirmada o cancelada (estado: %)', v_transfer.status;
  END IF;

  -- Actualizar estado
  UPDATE public.transfers
  SET status = 'CONFIRMADA', confirmed_at = NOW(), confirmed_by = p_user_id
  WHERE id = p_transfer_id;

  -- Procesar items
  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP
    -- Stock out del origen
    v_movement := public.register_stock_movement(
      p_product_id := v_item.product_id,
      p_store_id := v_transfer.origin_store_id,
      p_quantity := -v_item.quantity,
      p_movement_type := 'transfer_out',
      p_reference_id := p_transfer_id,
      p_user_id := p_user_id,
      p_unit_cost := v_item.unit_cost,
      p_operation_date := p_operation_date
    );
    v_movements := array_append(v_movements, v_movement);

    -- Stock in del destino
    SELECT * INTO v_dest_product FROM public.products
    WHERE sku = (SELECT sku FROM public.products WHERE id = v_item.product_id)
    AND store_id = v_transfer.destination_store_id
    FOR UPDATE;

    IF v_dest_product.id IS NULL THEN
      RAISE EXCEPTION 'ERR_DEST_PRODUCT_NOT_FOUND: Producto SKU no existe en tienda destino';
    END IF;

    v_movement := public.register_stock_movement(
      p_product_id := v_dest_product.id,
      p_store_id := v_transfer.destination_store_id,
      p_quantity := v_item.quantity,
      p_movement_type := 'transfer_in',
      p_reference_id := p_transfer_id,
      p_user_id := p_user_id,
      p_unit_cost := v_item.unit_cost,
      p_operation_date := p_operation_date
    );
    v_movements := array_append(v_movements, v_movement);
  END LOOP;

  -- FIX T5-05: auditoría server-side (no client-side)
  INSERT INTO public.audit_logs (user_id, store_id, action, entity_type, entity_id, details)
  VALUES (
    p_user_id,
    v_transfer.origin_store_id,
    'transfer_confirmed',
    'transfer',
    p_transfer_id,
    jsonb_build_object(
      'origin_store_id', v_transfer.origin_store_id,
      'destination_store_id', v_transfer.destination_store_id,
      'confirmed_at', NOW(),
      'items_count', (SELECT COUNT(*) FROM public.transfer_items WHERE transfer_id = p_transfer_id)
    )
  );

  RETURN jsonb_build_object('status', 'success', 'transfer_id', p_transfer_id, 'movements', to_jsonb(v_movements));
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.confirm_transfer(
  p_transfer_id UUID, p_user_id UUID, p_operation_date TIMESTAMPTZ DEFAULT NOW()
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER
AS $func$
DECLARE
  v_transfer RECORD; v_item RECORD; v_dest RECORD; v_mov JSONB;
  v_movements JSONB[] := ARRAY[]::JSONB[];
BEGIN
  SELECT * INTO v_transfer FROM public.transfers WHERE id = p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found'; END IF;
  IF v_transfer.status <> 'PENDIENTE' THEN RAISE EXCEPTION 'ERR_TRANSFER_NOT_PENDING'; END IF;

  UPDATE public.transfers SET status = 'CONFIRMADA', confirmed_at = NOW(), confirmed_by = p_user_id WHERE id = p_transfer_id;

  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP
    -- FIX F5-18: skip access check para origen
    v_mov := public.register_stock_movement(v_item.product_id, v_transfer.origin_store_id, -v_item.quantity,
      'transfer_out', p_transfer_id::text, p_user_id, NULL, NULL, v_item.unit_cost, NULL, p_operation_date, TRUE);
    v_movements := array_append(v_movements, v_mov);

    SELECT * INTO v_dest FROM public.products WHERE sku = (SELECT sku FROM public.products WHERE id = v_item.product_id) AND store_id = v_transfer.destination_store_id FOR UPDATE;
    IF v_dest.id IS NULL THEN RAISE EXCEPTION 'ERR_DEST_PRODUCT_NOT_FOUND'; END IF;

    -- FIX F5-11: pasar unit_cost para PMP en destino
    v_mov := public.register_stock_movement(v_dest.id, v_transfer.destination_store_id, v_item.quantity,
      'transfer_in', p_transfer_id::text, p_user_id, NULL, NULL, v_item.unit_cost, NULL, p_operation_date, FALSE);
    v_movements := array_append(v_movements, v_mov);
  END LOOP;

  INSERT INTO public.audit_logs (user_id, store_id, action, table_name, record_id, metadata)
  VALUES (p_user_id, v_transfer.origin_store_id, 'transfer_confirmed', 'transfers', p_transfer_id,
    jsonb_build_object('dest',v_transfer.destination_store_id,'at',NOW()));

  RETURN jsonb_build_object('status','success','transfer_id',p_transfer_id);
END;
$func$

CREATE OR REPLACE FUNCTION public.confirm_transfer(
  p_transfer_id uuid,
  p_user_id uuid,
  p_operation_date timestamp with time zone DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_transfer RECORD;
  v_item RECORD;
  v_dest RECORD;
  v_mov JSONB;
  v_movements JSONB[] := ARRAY[]::JSONB[];
  -- V2.12.9 anti-spoofing: solo service_role puede pasar p_user_id explícito
  v_caller_uid UUID := CASE
    WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid())
    ELSE auth.uid()
  END;
BEGIN
  -- V2.12.10 (nuevo): check de acceso al destino. Antes no había NINGÚN check.
  -- Cualquiera autenticado podía confirmar cualquier transferencia.
  SELECT * INTO v_transfer FROM public.transfers WHERE id = p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found'; END IF;
  IF v_transfer.status <> 'PENDIENTE' THEN RAISE EXCEPTION 'ERR_TRANSFER_NOT_PENDING'; END IF;

  -- V2.12.10: autorización — caller debe tener acceso al destino
  IF v_caller_uid IS NULL OR NOT public.has_store_access_as(v_caller_uid, v_transfer.destination_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;

  -- V2.12.10 (H7 fix): si requires_approval=TRUE y NO está aprobada, rechazar.
  -- Esto cierra la puerta trasera descrita en el audit.
  IF COALESCE(v_transfer.requires_approval, false) = true
     AND v_transfer.approved_at IS NULL THEN
    RAISE EXCEPTION 'ERR_TRANSFER_REQUIRES_APPROVAL';
  END IF;

  UPDATE public.transfers
    SET status = 'CONFIRMADA',
        confirmed_at = NOW(),
        confirmed_by = v_caller_uid
    WHERE id = p_transfer_id;

  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP
    -- FIX F5-18: skip access check para origen (el caller accede al destino)
    v_mov := public.register_stock_movement(v_item.product_id, v_transfer.origin_store_id, -v_item.quantity,
      'transfer_out', p_transfer_id::text, v_caller_uid, NULL, NULL, v_item.unit_cost, NULL, p_operation_date, TRUE);
    v_movements := array_append(v_movements, v_mov);

    SELECT * INTO v_dest FROM public.products
      WHERE sku = (SELECT sku FROM public.products WHERE id = v_item.product_id)
        AND store_id = v_transfer.destination_store_id FOR UPDATE;
    IF v_dest.id IS NULL THEN RAISE EXCEPTION 'ERR_DEST_PRODUCT_NOT_FOUND'; END IF;

    -- FIX F5-11: pasar unit_cost para PMP en destino
    v_mov := public.register_stock_movement(v_dest.id, v_transfer.destination_store_id, v_item.quantity,
      'transfer_in', p_transfer_id::text, v_caller_uid, NULL, NULL, v_item.unit_cost, NULL, p_operation_date, FALSE);
    v_movements := array_append(v_movements, v_mov);
  END LOOP;

  INSERT INTO public.audit_logs (user_id, store_id, action, table_name, record_id, metadata)
  VALUES (v_caller_uid, v_transfer.origin_store_id, 'transfer_confirmed', 'transfers', p_transfer_id,
    jsonb_build_object('dest', v_transfer.destination_store_id, 'at', NOW(),
      'requires_approval_was', COALESCE(v_transfer.requires_approval, false),
      'was_approved', v_transfer.approved_at IS NOT NULL));

  RETURN jsonb_build_object('status', 'success', 'transfer_id', p_transfer_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_transfer(
  p_transfer_id uuid,
  p_user_id uuid,
  p_operation_date timestamp with time zone DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public, pg_temp
AS $function$
DECLARE
  v_transfer RECORD;
  v_item RECORD;
  v_mov JSONB;
  v_movements JSONB[] := ARRAY[]::JSONB[];
  v_caller_uid UUID := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;
  v_reservation RECORD;
BEGIN
  SELECT * INTO v_transfer FROM public.transfers WHERE id = p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found'; END IF;
  IF v_transfer.status <> 'PENDIENTE' THEN RAISE EXCEPTION 'ERR_TRANSFER_NOT_PENDING'; END IF;

  -- Autorización: caller debe tener acceso al destino
  IF v_caller_uid IS NULL OR NOT public.has_store_access_as(v_caller_uid, v_transfer.destination_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;

  -- Approval check
  IF COALESCE(v_transfer.requires_approval, false) = true AND v_transfer.approved_at IS NULL THEN
    RAISE EXCEPTION 'ERR_TRANSFER_REQUIRES_APPROVAL';
  END IF;

  -- Validar stock disponible una vez más (por si hubo ventas entre crear y confirmar)
  -- stock_available = stock_current - reservas ACTIVE de ESTA transferencia
  -- Si stock_current < qty, no hay suficiente (la reserva ya está contada en stock_available)
  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP
    SELECT stock_current INTO v_reservation
    FROM public.products WHERE id = v_item.product_id AND store_id = v_transfer.origin_store_id FOR UPDATE;

    IF v_reservation < v_item.quantity THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK_AT_CONFIRM: producto %, stock %, solicitado %',
        v_item.product_id, v_reservation, v_item.quantity;
    END IF;
  END LOOP;

  -- Actualizar estado
  UPDATE public.transfers
    SET status = 'CONFIRMADA', confirmed_at = NOW(), confirmed_by = v_caller_uid
    WHERE id = p_transfer_id;

  -- Procesar items: consumir reserva + mover stock
  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP
    -- 1. Consumir reserva (cambiar status a CONSUMED)
    UPDATE public.inventory_reservations
      SET status = 'CONSUMED', consumed_at = NOW()
      WHERE reference_type = 'TRANSFER' AND reference_id = p_transfer_id
        AND product_id = v_item.product_id AND status = 'ACTIVE';

    -- 2. Descontar stock del origen (transfer_out)
    v_mov := public.register_stock_movement(
      v_item.product_id, v_transfer.origin_store_id, -v_item.quantity,
      'transfer_out', p_transfer_id::text, v_caller_uid, NULL, NULL,
      v_item.unit_cost, NULL, p_operation_date, TRUE
    );
    v_movements := array_append(v_movements, v_mov);

    -- 3. Añadir stock al destino (transfer_in) — usar destination_product_id
    v_mov := public.register_stock_movement(
      v_item.destination_product_id, v_transfer.destination_store_id, v_item.quantity,
      'transfer_in', p_transfer_id::text, v_caller_uid, NULL, NULL,
      v_item.unit_cost, NULL, p_operation_date, FALSE
    );
    v_movements := array_append(v_movements, v_mov);
  END LOOP;

  INSERT INTO public.audit_logs (user_id, store_id, action, table_name, record_id, metadata)
  VALUES (v_caller_uid, v_transfer.origin_store_id, 'transfer_confirmed', 'transfers', p_transfer_id,
    jsonb_build_object('dest', v_transfer.destination_store_id, 'at', NOW(),
      'requires_approval_was', COALESCE(v_transfer.requires_approval, false),
      'was_approved', v_transfer.approved_at IS NOT NULL,
      'reservations_consumed', (SELECT count(*) FROM public.inventory_reservations WHERE reference_id = p_transfer_id AND status = 'CONSUMED')));

  RETURN jsonb_build_object('status', 'success', 'transfer_id', p_transfer_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_transfer(
  p_transfer_id uuid,
  p_user_id uuid,
  p_operation_date timestamp with time zone DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public, pg_temp
AS $function$
DECLARE
  v_transfer RECORD;
  v_item RECORD;
  v_mov JSONB;
  v_movements JSONB[] := ARRAY[]::JSONB[];
  v_caller_uid UUID := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;
  v_stock_info JSONB;
  v_available NUMERIC;
  v_rows_affected INTEGER;
  v_ref_doc TEXT;
BEGIN
  SELECT * INTO v_transfer FROM public.transfers WHERE id = p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found'; END IF;
  IF v_transfer.status <> 'PENDIENTE' THEN RAISE EXCEPTION 'ERR_TRANSFER_NOT_PENDING'; END IF;

  -- Autorización: caller debe tener acceso al destino
  IF v_caller_uid IS NULL OR NOT public.has_store_access_as(v_caller_uid, v_transfer.destination_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;

  -- Approval check
  IF COALESCE(v_transfer.requires_approval, false) = true AND v_transfer.approved_at IS NULL THEN
    RAISE EXCEPTION 'ERR_TRANSFER_REQUIRES_APPROVAL';
  END IF;

  -- H-039: Validar stock disponible usando get_available_stock
  -- stock_available = stock_current - SUM(reservas ACTIVE)
  -- La reserva de ESTA transferencia está incluida en las ACTIVE,
  -- así que stock_available ya refleja que estas unidades están comprometadas.
  -- Si stock_available >= qty, hay suficiente para consumir la reserva.
  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP
    SELECT * INTO v_stock_info FROM public.get_available_stock(v_transfer.origin_store_id, v_item.product_id);

    IF NOT (v_stock_info->>'found')::boolean THEN
      RAISE EXCEPTION 'ERR_PRODUCT_NOT_FOUND_AT_CONFIRM: %', v_item.product_id;
    END IF;

    v_available := (v_stock_info->>'stock_available')::numeric;
    -- v_available ya incluye la resta de la reserva de esta transferencia
    -- Si v_available < 0, significa que otras operaciones consumieron el stock físico
    IF v_available < 0 THEN
      RAISE EXCEPTION 'ERR_INSUFFICIENT_STOCK_AT_CONFIRM: producto %, stock_fisico=%, reservado=%, disponible=%, solicitado=%',
        v_item.product_id,
        (v_stock_info->>'stock_current'),
        (v_stock_info->>'stock_reserved'),
        v_available,
        v_item.quantity;
    END IF;
  END LOOP;

  -- Actualizar estado
  UPDATE public.transfers
    SET status = 'CONFIRMADA', confirmed_at = NOW(), confirmed_by = v_caller_uid
    WHERE id = p_transfer_id;

  -- TC-3 H-045: reference_doc legible
  v_ref_doc := 'TRANSFERENCIA ' || UPPER(left(v_transfer.id::text, 8)) || ' ' ||
               left(v_transfer.origin_store_id::text, 8) || '→' ||
               left(v_transfer.destination_store_id::text, 8);

  -- Procesar items: consumir reserva + mover stock
  FOR v_item IN SELECT * FROM public.transfer_items WHERE transfer_id = p_transfer_id LOOP

    -- H-041: Consumir reserva — validar que afectó exactamente 1 fila
    UPDATE public.inventory_reservations
      SET status = 'CONSUMED', consumed_at = NOW()
      WHERE reference_type = 'TRANSFER'
        AND reference_id = p_transfer_id
        AND product_id = v_item.product_id
        AND status = 'ACTIVE';

    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    IF v_rows_affected = 0 THEN
      RAISE EXCEPTION 'ERR_RESERVATION_NOT_FOUND: No hay reserva ACTIVE para transferencia % producto %',
        p_transfer_id, v_item.product_id;
    END IF;

    -- Descontar stock del origen (transfer_out)
    v_mov := public.register_stock_movement(
      v_item.product_id, v_transfer.origin_store_id, -v_item.quantity,
      'transfer_out', v_ref_doc, v_caller_uid, NULL, NULL,
      v_item.unit_cost, NULL, p_operation_date, TRUE
    );
    v_movements := array_append(v_movements, v_mov);

    -- Añadir stock al destino (transfer_in) — usar destination_product_id
    v_mov := public.register_stock_movement(
      v_item.destination_product_id, v_transfer.destination_store_id, v_item.quantity,
      'transfer_in', v_ref_doc, v_caller_uid, NULL, NULL,
      v_item.unit_cost, NULL, p_operation_date, FALSE
    );
    v_movements := array_append(v_movements, v_mov);
  END LOOP;

  INSERT INTO public.audit_logs (user_id, store_id, action, table_name, record_id, metadata)
  VALUES (v_caller_uid, v_transfer.origin_store_id, 'transfer_confirmed', 'transfers', p_transfer_id,
    jsonb_build_object('dest', v_transfer.destination_store_id, 'at', NOW(),
      'requires_approval_was', COALESCE(v_transfer.requires_approval, false),
      'was_approved', v_transfer.approved_at IS NOT NULL,
      'reservations_consumed', (SELECT count(*) FROM public.inventory_reservations WHERE reference_id = p_transfer_id AND status = 'CONSUMED'),
      'reference_doc', v_ref_doc));

  RETURN jsonb_build_object('status', 'success', 'transfer_id', p_transfer_id);
END;
$function$

