CREATE OR REPLACE FUNCTION public.update_product_wac()
RETURNS TRIGGER AS $$
DECLARE
    v_current_stock NUMERIC;
    v_current_cost NUMERIC;
    v_new_stock NUMERIC;
    v_new_cost NUMERIC;
    v_store_id UUID;
BEGIN
    -- Get current data
    SELECT stock_current, cost_price INTO v_current_stock, v_current_cost
    FROM public.products WHERE id = NEW.product_id;

    -- Safety fallback for first reception
    v_current_stock := COALESCE(v_current_stock, 0);
    v_current_cost := COALESCE(v_current_cost, 0);

    v_new_stock := v_current_stock + NEW.quantity;

    IF v_new_stock > 0 THEN
        -- WAC = (Stock Actual * Costo Actual + Nueva Cantidad * Nuevo Costo) / Stock Total
        v_new_cost := ((v_current_stock * v_current_cost) + (NEW.quantity * NEW.unit_cost)) / v_new_stock;
    ELSE
        v_new_cost := NEW.unit_cost;
    END IF;

    UPDATE public.products
    SET cost_price = v_new_cost,
        updated_at = NOW()
    WHERE id = NEW.product_id;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.update_product_wac()
RETURNS TRIGGER AS $$
DECLARE
    v_current_stock NUMERIC;
    v_current_cost NUMERIC;
    v_new_stock NUMERIC;
    v_new_cost NUMERIC;
BEGIN
    -- CRITICAL: Lock the product row FOR UPDATE to prevent race conditions in WAC calculation
    SELECT stock_current, cost_price INTO v_current_stock, v_current_cost
    FROM public.products
    WHERE id = NEW.product_id
    FOR UPDATE;

    v_current_stock := COALESCE(v_current_stock, 0);
    v_current_cost := COALESCE(v_current_cost, 0);

    v_new_stock := v_current_stock + NEW.quantity;

    IF v_new_stock > 0 THEN
        v_new_cost := ((v_current_stock * v_current_cost) + (NEW.quantity * NEW.unit_cost)) / v_new_stock;
    ELSE
        v_new_cost := NEW.unit_cost;
    END IF;

    UPDATE public.products
    SET cost_price = v_new_cost,
        updated_at = NOW()
    WHERE id = NEW.product_id;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.update_product_wac()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
    v_current_stock NUMERIC;
    v_current_cost NUMERIC;
    v_new_stock NUMERIC;
    v_new_cost NUMERIC;
BEGIN
    -- Bypass durante restauración
    IF current_setting('app.restore_mode', true) = 'true' THEN
        RETURN NEW;
    END IF;

    SELECT stock_current, cost_average INTO v_current_stock, v_current_cost
    FROM public.products
    WHERE id = NEW.product_id
    FOR UPDATE;

    v_current_stock := COALESCE(v_current_stock, 0);
    v_current_cost := COALESCE(v_current_cost, 0);

    v_new_stock := v_current_stock + NEW.quantity;

    IF v_new_stock > 0 THEN
        v_new_cost := ((v_current_stock * v_current_cost) + (NEW.quantity * NEW.unit_cost)) / v_new_stock;
    ELSE
        v_new_cost := NEW.unit_cost;
    END IF;

    UPDATE public.products
    SET cost_average = v_new_cost,
        updated_at = NOW()
    WHERE id = NEW.product_id;

    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.update_product_wac()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_store_id UUID;
  v_total_cost NUMERIC := 0;
  v_total_qty NUMERIC := 0;
  v_service_costs NUMERIC := 0;
  v_current_wac NUMERIC;
BEGIN
  SELECT store_id INTO v_store_id FROM products WHERE id = NEW.product_id;
  IF v_store_id IS NULL THEN RETURN NEW; END IF;

  -- Sumar costos de receipt_items (costo directo de recepciones)
  SELECT COALESCE(SUM(ri.quantity * ri.unit_cost * COALESCE(ri.tasa_cambio_recepcion, 1.0)), 0)
  INTO v_total_cost
  FROM receipt_items ri
  JOIN receipts r ON r.id = ri.receipt_id
  WHERE ri.product_id = NEW.product_id AND r.store_id = v_store_id AND r.status = 'active';

  -- Sumar cantidades de receipt_items
  SELECT COALESCE(SUM(ri.quantity), 0)
  INTO v_total_qty
  FROM receipt_items ri
  JOIN receipts r ON r.id = ri.receipt_id
  WHERE ri.product_id = NEW.product_id AND r.store_id = v_store_id AND r.status = 'active';

  -- G4 NUEVO: Sumar costos de service_cost_distributions (servicios recibidos)
  SELECT COALESCE(SUM(scd.distribution_amount), 0)
  INTO v_service_costs
  FROM service_cost_distributions scd
  JOIN received_services rs ON rs.id = scd.service_id
  WHERE scd.product_id = NEW.product_id
    AND rs.store_id = v_store_id
    AND rs.status = 'active';

  -- Calcular WAC: (costo recepciones + costo servicios) / cantidad total
  IF v_total_qty > 0 THEN
    v_current_wac := (v_total_cost + v_service_costs) / v_total_qty;
  ELSE
    v_current_wac := 0;
  END IF;

  UPDATE products
  SET cost_average = v_current_wac, updated_at = NOW()
  WHERE id = NEW.product_id AND store_id = v_store_id;

  RETURN NEW;
END;
$function$

