        true
    );

    -- Log automatic creation
    INSERT INTO public.user_audit_log (
        performed_by,
        target_user_id,
        action,
        new_values
    ) VALUES (
        '00000000-0000-0000-0000-000000000000'::UUID,
        NEW.id,
        'USER_REGISTERED_PUBLICLY',
        jsonb_build_object('role', 'UserCosto', 'email', NEW.email)
    );

