END;
$$ LANGUAGE plpgsql SECURITY DEFINER

can_safely_delete_user.stmt_full:
CREATE OR REPLACE FUNCTION public.can_safely_delete_user(p_user_id UUID)
RETURNS BOOLEAN AS $$
DECLARE
    v_has_sales BOOLEAN;
    v_has_receipts BOOLEAN;
    v_has_transfers BOOLEAN;
    v_has_adjustments BOOLEAN;
    v_user_role user_role;
BEGIN
    -- Get user role
    SELECT role INTO v_user_role FROM public.profiles WHERE id = p_user_id;

    -- If role is 'costo', we consider it safe for now unless they somehow created something
    -- (The following checks will catch it anyway)

    -- Check Sales (as cashier)
    SELECT EXISTS (SELECT 1 FROM public.sales WHERE cashier_id = p_user_id) INTO v_has_sales;
    IF v_has_sales THEN RETURN FALSE; END IF;

    -- Check Receipts/Receptions
    SELECT EXISTS (SELECT 1 FROM public.receipts WHERE user_id = p_user_id) INTO v_has_receipts;
    IF v_has_receipts THEN RETURN FALSE; END IF;

    -- Check Transfers
    SELECT EXISTS (SELECT 1 FROM public.transfers WHERE created_by = p_user_id) INTO v_has_transfers;
    IF v_has_transfers THEN RETURN FALSE; END IF;

    -- Check Inventory Adjustments
    SELECT EXISTS (SELECT 1 FROM public.inventory_adjustments WHERE created_by = p_user_id) INTO v_has_adjustments;
    IF v_has_adjustments THEN RETURN FALSE; END IF;

    RETURN TRUE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.can_safely_delete_user(p_user_id UUID)
RETURNS BOOLEAN AS $$
DECLARE
    v_has_records BOOLEAN;
BEGIN
    -- Check Sales (as cashier)
    SELECT EXISTS (SELECT 1 FROM public.sales WHERE cashier_id = p_user_id) INTO v_has_records;
    IF v_has_records THEN RETURN FALSE; END IF;

    -- Check Receipts/Receptions
    SELECT EXISTS (SELECT 1 FROM public.receipts WHERE user_id = p_user_id) INTO v_has_records;
    IF v_has_records THEN RETURN FALSE; END IF;

    -- Check Transfers
    SELECT EXISTS (SELECT 1 FROM public.transfers WHERE created_by = p_user_id) INTO v_has_records;
    IF v_has_records THEN RETURN FALSE; END IF;

    -- Check Inventory Adjustments
    SELECT EXISTS (SELECT 1 FROM public.inventory_adjustments WHERE created_by = p_user_id) INTO v_has_records;
    IF v_has_records THEN RETURN FALSE; END IF;

    -- Check Cash Closures
    SELECT EXISTS (SELECT 1 FROM public.cash_closures WHERE user_id = p_user_id) INTO v_has_records;
    IF v_has_records THEN RETURN FALSE; END IF;

    -- Check Inventory Movements
    SELECT EXISTS (SELECT 1 FROM public.inventory_movements WHERE user_id = p_user_id) INTO v_has_records;
    IF v_has_records THEN RETURN FALSE; END IF;

    RETURN TRUE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions

managed_delete_user.stmt_full:
CREATE OR REPLACE FUNCTION public.managed_delete_user(p_user_id UUID)
RETURNS JSONB AS $$
BEGIN
    -- Security Check: Only admins can delete
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Solo los administradores pueden eliminar usuarios.';
    END IF;

    -- Cannot delete self
    IF p_user_id = auth.uid() THEN
        RAISE EXCEPTION 'ERR_CANNOT_DELETE_SELF: No puedes eliminar tu propio usuario.';
    END IF;

    -- Safety Check
    IF NOT public.can_safely_delete_user(p_user_id) THEN
        RAISE EXCEPTION 'ERR_USER_HAS_RECORDS: El usuario tiene registros operativos (ventas, compras o movimientos) y no puede ser eliminado por integridad de datos. Se recomienda desactivarlo.';
    END IF;

    -- Perform deletion (Cascades to memberships and other metadata)
    -- Note: Profiles table should have ON DELETE CASCADE where appropriate,
    -- but we are being careful by checking records first.

    -- Deleting from profiles will work if p_user_id is in auth.users too?
    -- Actually, to fully delete a user in Supabase, they must be removed from auth.users.
    -- This RPC only handles public schema cleanup. The Edge Function/API will handle auth.users.

    DELETE FROM public.profiles WHERE id = p_user_id;

    RETURN jsonb_build_object('success', true, 'message', 'Perfil de usuario eliminado correctamente.');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.managed_delete_user(p_user_id UUID)
RETURNS JSONB AS $$
BEGIN
    -- Security Check: Allow if service role (auth.uid() is null) or if current user is admin
    IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Solo los administradores pueden eliminar usuarios.';
    END IF;

    -- Cannot delete self
    IF p_user_id = auth.uid() THEN
        RAISE EXCEPTION 'ERR_CANNOT_DELETE_SELF: No puedes eliminar tu propio usuario.';
    END IF;

    -- Safety Check
    IF NOT public.can_safely_delete_user(p_user_id) THEN
        RAISE EXCEPTION 'ERR_USER_HAS_RECORDS: El usuario tiene registros operativos y no puede ser eliminado por integridad de datos. Se recomienda desactivarlo.';
    END IF;

    -- Perform deletion (Cascades to memberships and other metadata)
    -- We explicitly delete memberships first just in case
    DELETE FROM public.user_store_memberships WHERE user_id = p_user_id;

    -- Deleting from profiles
    DELETE FROM public.profiles WHERE id = p_user_id;

    RETURN jsonb_build_object('success', true, 'message', 'Perfil de usuario eliminado correctamente.');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions

log_audit_event.stmt_full:
CREATE OR REPLACE FUNCTION public.log_audit_event(
    p_action TEXT,
    p_payload JSONB,
    p_store_id UUID DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
    v_prev_hash TEXT;
    v_payload_hash TEXT;
    v_event_hash TEXT;
    v_event_id UUID;
    v_tenant_id UUID;
    v_role TEXT;
BEGIN
    SELECT tenant_id, role::text INTO v_tenant_id, v_role FROM public.profiles WHERE id = auth.uid();
    SELECT event_hash INTO v_prev_hash FROM public.audit_events ORDER BY utc_timestamp DESC LIMIT 1;

    v_payload_hash := encode(extensions.digest(p_payload::text, 'sha256'), 'hex');
    v_event_hash := encode(extensions.digest(v_payload_hash || COALESCE(v_prev_hash, '') || now()::text, 'sha256'), 'hex');

    INSERT INTO public.audit_events (
        actor_id, role, tenant_id, store_id, action, payload_hash, previous_event_hash, event_hash
    ) VALUES (
        auth.uid(), v_role, v_tenant_id, p_store_id, p_action, v_payload_hash, v_prev_hash, v_event_hash
    ) RETURNING id INTO v_event_id;

    RETURN v_event_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions

fn_process_receipt.stmt_full:
CREATE OR REPLACE FUNCTION public.fn_process_receipt(p_items jsonb, p_user_id uuid, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_receipt_id uuid;
    v_item jsonb;
    v_prod_id uuid;
    v_qty int;
    v_cost numeric;
    v_current_stock int;
    v_current_avg_cost numeric;
    v_new_stock int;
    v_new_avg_cost numeric;
    v_total_receipt numeric := 0;
    v_new_details jsonb;
    v_sku text;
    v_auth_user_id uuid := auth.uid();
BEGIN
    IF v_auth_user_id IS NOT NULL AND v_auth_user_id != p_user_id THEN
        RAISE EXCEPTION 'ERR_UNAUTHORIZED: Identity mismatch';
    END IF;

    INSERT INTO public.receipts (user_id, status, reference_doc)
    VALUES (p_user_id, 'active', p_reference)
    RETURNING id INTO v_receipt_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_sku := v_item->>'sku';
        v_qty := (v_item->>'quantity')::int;
        v_cost := (v_item->>'unit_cost')::numeric;
        v_new_details := v_item->'new_product_details';

        IF v_sku IS NULL OR v_sku = '' THEN
            RAISE EXCEPTION 'SKU es obligatorio';
        END IF;

        IF v_qty <= 0 THEN RAISE EXCEPTION 'Cantidad debe ser positiva'; END IF;

        IF v_new_details IS NOT NULL AND v_new_details != 'null'::jsonb THEN
            SELECT id INTO v_prod_id FROM public.products WHERE sku = v_sku;
            IF v_prod_id IS NULL THEN
                INSERT INTO public.products (name, sku, cost_price, price, stock_current, cost_average)
                VALUES (v_new_details->>'name', v_sku, v_cost, (v_new_details->>'price')::numeric, 0, 0)
                RETURNING id INTO v_prod_id;
            END IF;
        ELSE
             v_prod_id := (v_item->>'product_id')::uuid;
             IF v_prod_id IS NULL THEN SELECT id INTO v_prod_id FROM public.products WHERE sku = v_sku; END IF;
             IF v_prod_id IS NULL THEN RAISE EXCEPTION 'Producto no encontrado: %', v_sku; END IF;
        END IF;

        SELECT stock_current, cost_average INTO v_current_stock, v_current_avg_cost FROM public.products WHERE id = v_prod_id FOR UPDATE;
        v_new_stock := COALESCE(v_current_stock, 0) + v_qty;
        v_new_avg_cost := CASE WHEN v_new_stock > 0 THEN ((COALESCE(v_current_stock,0) * COALESCE(v_current_avg_cost,0)) + (v_qty * v_cost)) / v_new_stock ELSE v_cost END;

        INSERT INTO public.receipt_items (receipt_id, product_id, quantity, unit_cost) VALUES (v_receipt_id, v_prod_id, v_qty, v_cost);
        UPDATE public.products SET stock_current = v_new_stock, cost_average = v_new_avg_cost, cost_price = v_cost WHERE id = v_prod_id;
        INSERT INTO public.inventory_movements (product_id, type, quantity_change, reference_id, user_id, balance_after)
        VALUES (v_prod_id, 'IN_RECEIPT', v_qty, v_receipt_id, p_user_id, v_new_stock);
        v_total_receipt := v_total_receipt + (v_qty * v_cost);
    END LOOP;
    UPDATE public.receipts SET total_cost = v_total_receipt WHERE id = v_receipt_id;
    RETURN v_receipt_id;
END;
$function$

soft_delete_store.stmt_full:
CREATE OR REPLACE FUNCTION public.soft_delete_store(
  p_store_id UUID,
  p_deleted_by UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_result JSONB;
BEGIN
  -- Verify the store exists and is active
  IF NOT EXISTS (SELECT 1 FROM stores WHERE id = p_store_id AND is_active = true) THEN
    RAISE EXCEPTION 'Tienda no encontrada o ya inactiva';
  END IF;

  -- 1. Soft-delete the store
  UPDATE stores SET is_active = false WHERE id = p_store_id;

  -- 2. Revoke all memberships (same transaction — guaranteed atomic)
  UPDATE user_store_memberships
  SET status = 'revoked'
  WHERE store_id = p_store_id AND status = 'active';

  -- 3. Clear active_store_id references for all users pointing to this store
  UPDATE profiles
  SET active_store_id = NULL
  WHERE active_store_id = p_store_id;

  -- 4. Log the deletion
  INSERT INTO audit_logs (action, table_name, record_id, store_id, metadata)
  VALUES (
    'store_soft_deleted',
    'stores',
    p_store_id,
    p_store_id,
    jsonb_build_object(
      'deleted_by', p_deleted_by,
      'deleted_at', now()
    )
  );

  -- Return confirmation
  SELECT jsonb_build_object(
    'store_id', p_store_id,
    'is_active', false,
    'memberships_revoked', (SELECT count(*) FROM user_store_memberships WHERE store_id = p_store_id AND status = 'revoked'),
    'profiles_cleared', (SELECT count(*) FROM profiles WHERE active_store_id IS NULL AND id IN (
      SELECT user_id FROM user_store_memberships WHERE store_id = p_store_id
    ))
  ) INTO v_result;

  RETURN v_result;
END;
$$

CREATE OR REPLACE FUNCTION public.soft_delete_store(
  p_store_id UUID,
  p_deleted_by UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_caller_uid UUID := CASE WHEN auth.role() = 'service_role'
    THEN COALESCE(p_deleted_by, auth.uid()) ELSE auth.uid() END;
  v_result JSONB;
  v_validation JSONB;
  v_blockers TEXT;
BEGIN
  -- Anti-spoofing: verificar que el caller tiene acceso
  IF v_caller_uid IS NULL OR NOT public.has_store_access_as(v_caller_uid, p_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;

  -- Verificar que la tienda existe y está activa
  IF NOT EXISTS (SELECT 1 FROM stores WHERE id = p_store_id AND is_active = true) THEN
    RAISE EXCEPTION 'Tienda no encontrada o ya inactiva';
  END IF;

  -- H-007/008/009: Validar dependencias empresariales antes de eliminar
  SELECT * INTO v_validation FROM public.validate_store_can_be_modified(p_store_id, 'soft_delete');

  IF NOT (v_validation->>'can_modify')::boolean THEN
    SELECT string_agg(blocker->>'message', '; ')
    INTO v_blockers
    FROM jsonb_array_elements(v_validation->'blockers') AS blocker;

    RAISE EXCEPTION 'ERR_STORE_HAS_DEPENDENCIES: %', COALESCE(v_blockers, 'Hay dependencias pendientes');
  END IF;

  -- 1. Soft-delete the store
  UPDATE stores SET is_active = false WHERE id = p_store_id;

  -- 2. Revoke all memberships
  UPDATE user_store_memberships
  SET status = 'revoked'
  WHERE store_id = p_store_id AND status = 'active';

  -- 3. Clear active_store_id references
  UPDATE profiles SET active_store_id = NULL WHERE active_store_id = p_store_id;

  -- 4. Log the deletion (usar v_caller_uid, no p_deleted_by)
  INSERT INTO audit_logs (action, table_name, record_id, store_id, metadata)
  VALUES (
    'store_soft_deleted', 'stores', p_store_id, p_store_id,
    jsonb_build_object(
      'deleted_by', v_caller_uid,
      'deleted_at', now(),
      'memberships_revoked', (SELECT count(*) FROM user_store_memberships WHERE store_id = p_store_id AND status = 'revoked')
    )
  );

  -- 5. Retornar resultado con count correcto (H-013 fix)
  SELECT jsonb_build_object(
    'store_id', p_store_id,
    'is_active', false,
    'memberships_revoked', (SELECT count(*) FROM user_store_memberships WHERE store_id = p_store_id AND status = 'revoked'),
    'profiles_cleared', (SELECT count(*) FROM profiles WHERE id IN (
      SELECT user_id FROM user_store_memberships WHERE store_id = p_store_id
    ) AND active_store_id IS NULL)
  ) INTO v_result;

  RETURN v_result;
END;
$$

get_or_create_product_cost_sheet.stmt_full:
CREATE OR REPLACE FUNCTION public.get_or_create_product_cost_sheet(
  p_product_id UUID,
  p_store_id UUID,
  p_template_id TEXT DEFAULT NULL,
  p_modalidad TEXT DEFAULT NULL,
  p_pdf_format TEXT DEFAULT 'res148'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cost_sheet_id UUID;
  v_template_id TEXT;
  v_modalidad TEXT;
  v_result JSONB;
BEGIN
  -- Authorization check: caller must be a member of the target store
  IF NOT (public.is_global_admin() OR public.has_store_role(p_store_id, ARRAY['admin', 'manager', 'encargado', 'costo'])) THEN
    RAISE EXCEPTION 'Sin permisos para acceder a las fichas de costo de esta tienda';
  END IF;

  -- 1. Check if product already has a cost sheet
  SELECT cost_sheet_id INTO v_cost_sheet_id
  FROM products WHERE id = p_product_id;

  IF v_cost_sheet_id IS NOT NULL THEN
    -- Return existing cost sheet data
    SELECT jsonb_build_object(
      'id', id,
      'product_id', product_id,
      'store_id', store_id,
      'template_id', template_id,
      'modalidad', modalidad,
      'calculated_data', calculated_data,
      'cost_price', cost_price,
      'cost_price_updated_at', cost_price_updated_at,
      'sync_status', sync_status,
      'exists', true
    ) INTO v_result
    FROM product_cost_sheets
    WHERE id = v_cost_sheet_id AND deleted_at IS NULL;

    IF v_result IS NOT NULL THEN
      RETURN v_result;
    END IF;
  END IF;

  -- 2. Resolve template: explicit parameter > store default > error
  IF p_template_id IS NOT NULL THEN
    v_template_id := p_template_id;
    v_modalidad := COALESCE(p_modalidad, 'produccion');
  ELSE
    -- Get store's default template
    SELECT sct.template_id, sct.modalidad INTO v_template_id, v_modalidad
    FROM store_cost_templates sct
    WHERE sct.store_id = p_store_id AND sct.is_active = true;

    IF v_template_id IS NULL THEN
      RAISE EXCEPTION 'No hay plantilla de FC asignada a esta tienda. Configure una plantilla predeterminada primero.';
    END IF;
  END IF;

  -- 3. Return template info for client-side calculation
  -- (The actual calculation uses the TypeScript cost-engine on the API route)
  RETURN jsonb_build_object(
    'product_id', p_product_id,
    'store_id', p_store_id,
    'template_id', v_template_id,
    'modalidad', v_modalidad,
    'pdf_format', COALESCE(p_pdf_format, 'res148'),
    'exists', false,
    'needs_calculation', true
  );
END;
$$

