CREATE OR REPLACE FUNCTION public.validate_operation_date(p_new_date TIMESTAMP WITH TIME ZONE)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_max_date TIMESTAMP WITH TIME ZONE;
  v_max_date_str TEXT;
BEGIN
  IF p_new_date IS NULL THEN
    RETURN; -- sin fecha = usar NOW() implícitamente, no bloquea
  END IF;

  SELECT public.get_global_max_operation_date() INTO v_max_date;

  IF v_max_date IS NOT NULL AND p_new_date < v_max_date THEN
    v_max_date_str := to_char(v_max_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI');
    RAISE EXCEPTION 'ERR_BACKDATED_DOCUMENT: La fecha % es anterior a la fecha mínima permitida (%). No se puede retroceder en el tiempo operativo.',
      to_char(p_new_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI'),
      v_max_date_str
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_operation_date(
  p_new_date TIMESTAMP WITH TIME ZONE,
  p_store_id UUID DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_max_date TIMESTAMP WITH TIME ZONE;
  v_max_date_str TEXT;
  v_store_label TEXT;
BEGIN
  IF p_new_date IS NULL THEN
    RETURN; -- sin fecha = usar NOW() implícitamente, no bloquea
  END IF;

  -- Obtener MAX de la tienda específica (o global si no hay store_id)
  SELECT public.get_global_max_operation_date(p_store_id) INTO v_max_date;

  IF v_max_date IS NOT NULL AND p_new_date < v_max_date THEN
    v_max_date_str := to_char(v_max_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI');
    v_store_label := CASE WHEN p_store_id IS NULL THEN 'global' ELSE 'de la tienda' END;
    RAISE EXCEPTION 'ERR_BACKDATED_DOCUMENT: La fecha % es anterior a la fecha mínima permitida % (%). No se puede retroceder en el tiempo operativo.',
      to_char(p_new_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI'),
      v_max_date_str,
      v_store_label
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_operation_date(
  p_new_date TIMESTAMP WITH TIME ZONE,
  p_store_id UUID DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_max_date TIMESTAMP WITH TIME ZONE;
  v_max_date_str TEXT;
  v_store_label TEXT;
  v_lock_key BIGINT;
BEGIN
  IF p_new_date IS NULL THEN
    RETURN;
  END IF;

  -- FIX: Advisory lock per-store para prevenir race condition.
  -- Dos transacciones que validan la misma tienda se serializan.
  -- La segunda espera a que la primera haga commit (con su nuevo documento)
  -- antes de leer el MAX, garantizando que vea la fecha actualizada.
  --
  -- Usamos un hash del store_id como lock key para distribuir locks.
  -- Si p_store_id es NULL, usamos lock key 0 (lock global).
  IF p_store_id IS NOT NULL THEN
    v_lock_key := hashtext(p_store_id::text);
  ELSE
    v_lock_key := 0;
  END IF;

  -- Bloquear hasta obtener el lock (se libera al final de la transacción)
  PERFORM pg_advisory_xact_lock(v_lock_key);

  -- Ahora leer el MAX con garantía de que no hay otra transacción
  -- concurrente que esté insertando un documento para esta tienda
  SELECT public.get_global_max_operation_date(p_store_id) INTO v_max_date;

  IF v_max_date IS NOT NULL AND p_new_date < v_max_date THEN
    v_max_date_str := to_char(v_max_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI');
    v_store_label := CASE WHEN p_store_id IS NULL THEN 'global' ELSE 'de la tienda' END;
    RAISE EXCEPTION 'ERR_BACKDATED_DOCUMENT: La fecha % es anterior a la fecha mínima permitida % (%). No se puede retroceder en el tiempo operativo.',
      to_char(p_new_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI'),
      v_max_date_str,
      v_store_label
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_operation_date(
  p_new_date timestamp with time zone,
  p_store_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public, pg_temp
AS $function$
DECLARE
  v_max_date timestamptz;
BEGIN
  -- Bloquear el store para serializar validación (existente)
  PERFORM pg_advisory_xact_lock(hashtext(p_store_id::text));

  -- Validar forward-only (existente)
  SELECT MAX(created_at) INTO v_max_date FROM public.transactions WHERE store_id = p_store_id;
  IF v_max_date IS NOT NULL AND p_new_date < v_max_date THEN
    RAISE EXCEPTION 'ERR_BACKDATED_DOCUMENT: date % is before max %', p_new_date, v_max_date;
  END IF;

  -- Iteración Fiscal (F-C3): Bloquear ventas en períodos fiscales cerrados/locked
  IF EXISTS (
    SELECT 1 FROM public.fiscal_closings
    WHERE store_id = p_store_id
      AND status IN ('closed', 'locked')
      AND p_new_date >= make_date(period_year, period_month, 1)
      AND p_new_date < make_date(period_year, period_month, 1) + interval '1 month'
  ) THEN
    RAISE EXCEPTION 'ERR_FISCAL_PERIOD_CLOSED: date % is within a closed/locked fiscal period', p_new_date;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_operation_date(
  p_new_date TIMESTAMP WITH TIME ZONE,
  p_store_id UUID DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_min_date TIMESTAMP WITH TIME ZONE;
  v_max_date TIMESTAMP WITH TIME ZONE;
  v_min_date_str TEXT;
BEGIN
  IF p_new_date IS NULL THEN
    RETURN; -- sin fecha = usar NOW() implícitamente, no bloquea
  END IF;

  -- PR-4.4C: política lookback 2 meses (reemplaza forward-only)
  -- Permite fechas desde (NOW() - 2 meses) hasta (NOW() + 1 día)
  v_min_date := NOW() - INTERVAL '2 months';
  v_max_date := NOW() + INTERVAL '1 day';

  IF p_new_date < v_min_date THEN
    v_min_date_str := to_char(v_min_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY');
    RAISE EXCEPTION 'ERR_BACKDATED_DOCUMENT: La fecha % es anterior al límite histórico permitido de 2 meses (mínimo: %). No se pueden registrar operaciones con más de 2 meses de antigüedad.',
      to_char(p_new_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY'),
      v_min_date_str
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_new_date > v_max_date THEN
    RAISE EXCEPTION 'ERR_FUTURE_DATED_DOCUMENT: La fecha % es posterior al máximo permitido (hoy + 1 día). No se pueden registrar operaciones con fechas futuras.',
      to_char(p_new_date AT TIME ZONE 'America/Havana', 'DD/MM/YYYY HH24:MI')
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_operation_date(
  p_new_date TIMESTAMP WITH TIME ZONE,
  p_store_id UUID DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_today_business DATE;
  v_min_date_business DATE;
  v_max_date_business DATE;
  v_new_date_business DATE;
BEGIN
  IF p_new_date IS NULL THEN
    RETURN;
  END IF;

  -- PR-4.4E: comparar fechas de NEGOCIO (date-only) en timezone America/Havana
  -- Evita edge case de timezone donde 2026-06-10T00:00:00Z fallaba por estar
  -- 6 horas detrás de NOW() (2026-06-10T06:15:00Z)
  v_today_business := (NOW() AT TIME ZONE 'America/Havana')::DATE;
  v_min_date_business := v_today_business - INTERVAL '2 months';
  v_max_date_business := v_today_business + INTERVAL '1 day';
  v_new_date_business := (p_new_date AT TIME ZONE 'America/Havana')::DATE;

  IF v_new_date_business < v_min_date_business THEN
    RAISE EXCEPTION 'ERR_BACKDATED_DOCUMENT: La fecha % es anterior al límite histórico permitido de 2 meses (mínimo: %). No se pueden registrar operaciones con más de 2 meses de antigüedad.',
      to_char(v_new_date_business, 'DD/MM/YYYY'),
      to_char(v_min_date_business, 'DD/MM/YYYY')
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_new_date_business > v_max_date_business THEN
    RAISE EXCEPTION 'ERR_FUTURE_DATED_DOCUMENT: La fecha % es posterior al máximo permitido (hoy + 1 día). No se pueden registrar operaciones con fechas futuras.',
      to_char(v_new_date_business, 'DD/MM/YYYY')
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_operation_date(
