CREATE OR REPLACE FUNCTION public.record_counted_quantity(
  p_count_id UUID,
  p_product_id UUID,
  p_counted_quantity NUMERIC,
  p_user_id UUID DEFAULT NULL,
  p_notes TEXT DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql
